--
-- Name: acquire_job_lock(text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.acquire_job_lock(p_job_name text, p_locked_by text, p_ttl_seconds integer DEFAULT 300) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_acquired BIGINT;
BEGIN
  -- Try to insert (new lock) or update (expired lock)
  INSERT INTO public.job_locks (job_name, locked_by, locked_at, expires_at, run_count)
  VALUES (p_job_name, p_locked_by, now(), now() + (p_ttl_seconds || ' seconds')::INTERVAL, 1)
  ON CONFLICT (job_name) DO UPDATE
    SET locked_by = p_locked_by,
        locked_at = now(),
        expires_at = now() + (p_ttl_seconds || ' seconds')::INTERVAL,
        run_count = public.job_locks.run_count + 1
    WHERE public.job_locks.expires_at < now();  -- Only if expired

  GET DIAGNOSTICS v_acquired = ROW_COUNT;
  RETURN v_acquired > 0;
END;
$$;


ALTER FUNCTION public.acquire_job_lock(p_job_name text, p_locked_by text, p_ttl_seconds integer) OWNER TO postgres;

--
-- Name: add_chat_participant(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.add_chat_participant(p_room_id uuid, p_user_id uuid, p_role character varying DEFAULT 'member'::character varying) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  INSERT INTO "ChatParticipant" (room_id, user_id, role)
  VALUES (p_room_id, p_user_id, p_role)
  ON CONFLICT (room_id, user_id) 
  DO UPDATE SET 
    is_active = TRUE,
    left_at = NULL;
  
  RETURN TRUE;
EXCEPTION
  WHEN OTHERS THEN
    RETURN FALSE;
END;
$$;


ALTER FUNCTION public.add_chat_participant(p_room_id uuid, p_user_id uuid, p_role character varying) OWNER TO postgres;

