--
-- Name: apply_business_role_preset(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_business_role_preset(p_business_user_id uuid, p_user_id uuid, p_preset_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_role   public.business_role_base;
  v_grants public.business_permission[];
  v_denies public.business_permission[];
BEGIN
  IF NOT public.business_has_permission(
    p_business_user_id, 'team.manage'::public.business_permission, auth.uid()
  ) THEN
    RAISE EXCEPTION 'Unauthorized: requires team.manage';
  END IF;

  SELECT role_base, grant_perms, deny_perms
  INTO v_role, v_grants, v_denies
  FROM public."BusinessRolePreset"
  WHERE key = p_preset_key;

  IF v_role IS NULL THEN
    RAISE EXCEPTION 'Unknown preset key: %', p_preset_key;
  END IF;

  -- Upsert team membership
  INSERT INTO public."BusinessTeam"(
    business_user_id, user_id, role_base, invited_by, is_active
  ) VALUES (
    p_business_user_id, p_user_id, v_role, auth.uid(), true
  )
  ON CONFLICT (business_user_id, user_id) DO UPDATE
    SET role_base = EXCLUDED.role_base,
        is_active = true,
        updated_at = now();

  -- Clear existing overrides
  DELETE FROM public."BusinessPermissionOverride"
  WHERE business_user_id = p_business_user_id AND user_id = p_user_id;

  -- Apply grants
  IF v_grants IS NOT NULL AND array_length(v_grants, 1) > 0 THEN
    INSERT INTO public."BusinessPermissionOverride"(
      business_user_id, user_id, permission, allowed, created_by
    )
    SELECT p_business_user_id, p_user_id, perm, true, auth.uid()
    FROM unnest(v_grants) AS perm
    ON CONFLICT (business_user_id, user_id, permission)
    DO UPDATE SET allowed = true, updated_at = now();
  END IF;

  -- Apply denies
  IF v_denies IS NOT NULL AND array_length(v_denies, 1) > 0 THEN
    INSERT INTO public."BusinessPermissionOverride"(
      business_user_id, user_id, permission, allowed, created_by
    )
    SELECT p_business_user_id, p_user_id, perm, false, auth.uid()
    FROM unnest(v_denies) AS perm
    ON CONFLICT (business_user_id, user_id, permission)
    DO UPDATE SET allowed = false, updated_at = now();
  END IF;

  -- Audit
  BEGIN
    INSERT INTO public."BusinessAuditLog"(
      business_user_id, actor_user_id, action, target_type, target_id, metadata
    ) VALUES (
      p_business_user_id, auth.uid(), 'apply_role_preset',
      'BusinessTeam', p_user_id,
      jsonb_build_object('preset_key', p_preset_key, 'role_base', v_role::text)
    );
  EXCEPTION WHEN OTHERS THEN NULL;
  END;
END;
$$;


ALTER FUNCTION public.apply_business_role_preset(p_business_user_id uuid, p_user_id uuid, p_preset_key text) OWNER TO postgres;

--
-- Name: apply_home_role_preset(uuid, uuid, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.apply_home_role_preset(p_home_id uuid, p_user_id uuid, p_preset_key text, p_start_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
declare
  v_role public.home_role_base;
  v_grants public.home_permission[];
  v_denies public.home_permission[];
begin
  -- Only home member-managers can apply presets
  if not public.home_has_permission(p_home_id, 'members.manage'::public.home_permission, auth.uid()) then
    raise exception 'Unauthorized: requires members.manage';
  end if;

  select role_base, grant_perms, deny_perms
  into v_role, v_grants, v_denies
  from public."HomeRolePreset"
  where key = p_preset_key;

  if v_role is null then
    raise exception 'Unknown preset key: %', p_preset_key;
  end if;

  -- Ensure HomeOccupancy row exists (upsert) and set role_base + dates
  insert into public."HomeOccupancy"(home_id, user_id, role, role_base, start_at, end_at, is_active, created_at, updated_at)
  values (p_home_id, p_user_id, v_role::text, v_role, p_start_at, p_end_at, true, now(), now())
  on conflict (home_id, user_id) do update
    set role_base = excluded.role_base,
        role = excluded.role,
        start_at = excluded.start_at,
        end_at = excluded.end_at,
        is_active = true,
        updated_at = now();

  -- Clear existing overrides for this user+home (so preset is deterministic)
  delete from public."HomePermissionOverride"
  where home_id = p_home_id and user_id = p_user_id;

  -- Apply grants
  if v_grants is not null then
    insert into public."HomePermissionOverride"(home_id, user_id, permission, allowed, created_by)
    select p_home_id, p_user_id, perm, true, auth.uid()
    from unnest(v_grants) as perm
    on conflict (home_id, user_id, permission) do update set allowed = excluded.allowed, updated_at = now();
  end if;

  -- Apply denies
  if v_denies is not null then
    insert into public."HomePermissionOverride"(home_id, user_id, permission, allowed, created_by)
    select p_home_id, p_user_id, perm, false, auth.uid()
    from unnest(v_denies) as perm
    on conflict (home_id, user_id, permission) do update set allowed = excluded.allowed, updated_at = now();
  end if;

  -- Audit (best-effort)
  begin
    insert into public."HomeAuditLog"(home_id, actor_user_id, action, target_type, target_id, metadata)
    values (
      p_home_id,
      auth.uid(),
      'apply_role_preset',
      'HomeOccupancy',
      p_user_id,
      jsonb_build_object('preset_key', p_preset_key, 'role_base', v_role::text)
    );
  exception when others then
    -- ignore if audit table missing or RLS blocks (shouldn't)
    null;
  end;
end $$;


ALTER FUNCTION public.apply_home_role_preset(p_home_id uuid, p_user_id uuid, p_preset_key text, p_start_at timestamp with time zone, p_end_at timestamp with time zone) OWNER TO postgres;

--
-- Name: audience_identity_validate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.audience_identity_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW."public_persona_id" IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1
      FROM "public"."PublicPersona" pp
      WHERE pp."id" = NEW."public_persona_id"
        AND pp."user_id" = NEW."user_id"
    ) THEN
      RAISE EXCEPTION 'AudienceIdentity public_persona_id must belong to the same user';
    END IF;
  END IF;

  IF EXISTS (
    SELECT 1
    FROM "public"."PublicPersona" pp
    WHERE pp."handle_normalized" = NEW."handle_normalized"
      AND pp."user_id" <> NEW."user_id"
  ) THEN
    RAISE EXCEPTION 'Audience identity handle conflicts with a Beacon handle';
  END IF;

  NEW."updated_at" = now();
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.audience_identity_validate() OWNER TO postgres;

--
-- Name: auto_archive_expired_posts(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_archive_expired_posts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  archived_count integer := 0;
  ttl_row RECORD;
  affected_count bigint;
BEGIN
  -- Archive posts that exceeded their category TTL
  FOR ttl_row IN
    SELECT post_type, ttl_days FROM "public"."PostCategoryTTL" WHERE ttl_days > 0
  LOOP
    UPDATE "public"."Post"
    SET archived_at = now(),
        archive_reason = 'expired'
    WHERE post_type = ttl_row.post_type
      AND archived_at IS NULL
      AND created_at < (now() - (ttl_row.ttl_days || ' days')::interval);

    GET DIAGNOSTICS affected_count = ROW_COUNT;
  archived_count := archived_count + affected_count;
  END LOOP;

  -- Archive deals past their explicit expiration
  UPDATE "public"."Post"
  SET archived_at = now(),
      archive_reason = 'expired'
  WHERE post_type IN ('deal', 'deals_promos')
    AND archived_at IS NULL
    AND deal_expires_at IS NOT NULL
    AND deal_expires_at < now();

  GET DIAGNOSTICS affected_count = ROW_COUNT;
  archived_count := archived_count + affected_count;

  -- Archive events past their end date (with 24h grace period)
  UPDATE "public"."Post"
  SET archived_at = now(),
      archive_reason = 'expired'
  WHERE post_type = 'event'
    AND archived_at IS NULL
    AND event_end_date IS NOT NULL
    AND event_end_date < (now() - interval '24 hours');

  GET DIAGNOSTICS affected_count = ROW_COUNT;
  archived_count := archived_count + affected_count;

  -- Archive expired stories
  UPDATE "public"."Post"
  SET archived_at = now(),
      archive_reason = 'expired'
  WHERE is_story = true
    AND archived_at IS NULL
    AND story_expires_at IS NOT NULL
    AND story_expires_at < now();

  GET DIAGNOSTICS affected_count = ROW_COUNT;
  archived_count := archived_count + affected_count;

  RETURN archived_count;
END;
$$;


ALTER FUNCTION public.auto_archive_expired_posts() OWNER TO postgres;

--
-- Name: batch_endorsement_counts(uuid[], uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.batch_endorsement_counts(p_business_user_ids uuid[], p_viewer_home_id uuid, p_radius_meters integer DEFAULT 8047) RETURNS TABLE(business_user_id uuid, endorsement_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_viewer_location  geography;
BEGIN
  -- Get viewer home location
  SELECT h.location INTO v_viewer_location
  FROM "Home" h
  WHERE h.id = p_viewer_home_id;

  IF v_viewer_location IS NULL THEN
    -- Return zero counts for all requested businesses
    RETURN QUERY
    SELECT unnest(p_business_user_ids), 0::BIGINT;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    e.business_user_id,
    COUNT(*)::BIGINT AS endorsement_count
  FROM "NeighborEndorsement" e
  JOIN "Home" endorser_home ON endorser_home.id = e.endorser_home_id
  WHERE e.business_user_id = ANY(p_business_user_ids)
    AND ST_DWithin(endorser_home.location, v_viewer_location, p_radius_meters)
    -- Verified occupancy gate
    AND EXISTS (
      SELECT 1 FROM "HomeOccupancy" ho
      WHERE ho.home_id = e.endorser_home_id
        AND ho.user_id = e.endorser_user_id
        AND ho.is_active = true
        AND ho.role_base NOT IN ('guest')
    )
    -- Minimum home age: 14 days
    AND endorser_home.created_at <= (now() - INTERVAL '14 days')
  GROUP BY e.business_user_id;
END;
$$;


ALTER FUNCTION public.batch_endorsement_counts(p_business_user_ids uuid[], p_viewer_home_id uuid, p_radius_meters integer) OWNER TO postgres;

--
-- Name: booking_enforce_daily_cap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.booking_enforce_daily_cap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cap integer;
  v_count integer;
  v_day date;
BEGIN
  -- Co-host reservation shadows mirror their primary row; the primary already consumed the cap.
  IF NEW.cohost_of_booking_id IS NOT NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.event_type_id IS NULL OR NEW.status NOT IN ('pending', 'confirmed') THEN
    RETURN NEW;
  END IF;

  SELECT daily_cap INTO v_cap FROM "public"."EventType" WHERE id = NEW.event_type_id;
  IF COALESCE(v_cap, 0) <= 0 THEN
    RETURN NEW;
  END IF;

  v_day := (NEW.start_at AT TIME ZONE 'UTC')::date;

  -- Serialize concurrent bookings for the same (event_type, UTC day).
  PERFORM pg_advisory_xact_lock(hashtext(NEW.event_type_id::text || '|day|' || v_day::text)::bigint);

  SELECT count(*) INTO v_count
  FROM "public"."Booking"
  WHERE event_type_id = NEW.event_type_id
    AND (start_at AT TIME ZONE 'UTC')::date = v_day
    AND status IN ('pending', 'confirmed')
    AND cohost_of_booking_id IS NULL
    AND id <> NEW.id;

  IF v_count >= v_cap THEN
    RAISE EXCEPTION 'DAILY_CAP_REACHED: % of % bookings taken', v_count, v_cap USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.booking_enforce_daily_cap() OWNER TO postgres;

--
-- Name: booking_enforce_group_cap(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.booking_enforce_group_cap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_cap  integer;
  v_mode text;
  v_count integer;
BEGIN
  -- Only relevant for active bookings tied to an event type.
  IF NEW.event_type_id IS NULL OR NEW.status NOT IN ('pending', 'confirmed') THEN
    RETURN NEW;
  END IF;

  SELECT seat_cap, assignment_mode::text INTO v_cap, v_mode
  FROM "public"."EventType" WHERE id = NEW.event_type_id;

  -- Non-group, or group with a single seat (covered by the exclusion constraint) — nothing to do.
  IF v_mode IS DISTINCT FROM 'group' OR COALESCE(v_cap, 1) <= 1 THEN
    RETURN NEW;
  END IF;

  -- Serialize concurrent bookings for the SAME (event_type, slot) so the count+insert is atomic.
  PERFORM pg_advisory_xact_lock(hashtext(NEW.event_type_id::text || '|' || NEW.start_at::text)::bigint);

  SELECT count(*) INTO v_count
  FROM "public"."Booking"
  WHERE event_type_id = NEW.event_type_id
    AND start_at = NEW.start_at
    AND status IN ('pending', 'confirmed')
    AND id <> NEW.id; -- exclude self (relevant on UPDATE; NEW.id is already populated on INSERT)

  IF v_count >= v_cap THEN
    RAISE EXCEPTION 'GROUP_SLOT_FULL: % of % seats taken', v_count, v_cap USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.booking_enforce_group_cap() OWNER TO postgres;

--
-- Name: booking_set_guard_range(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.booking_set_guard_range() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- Occupied range = prep (buffer_before) before the start, wind-down (buffer_after) after the end.
  NEW.guard_start := NEW.start_at - "make_interval"("mins" => COALESCE(NEW.buffer_before_min, 0));
  NEW.guard_end   := NEW.end_at   + "make_interval"("mins" => COALESCE(NEW.buffer_after_min, 0));
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.booking_set_guard_range() OWNER TO postgres;

--
-- Name: browse_listings_by_distance(double precision, double precision, double precision, double precision, double precision, double precision, text, text, boolean, boolean, text, numeric, numeric, text, boolean, text, timestamp with time zone, double precision, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.browse_listings_by_distance(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_ref_lat double precision, p_ref_lng double precision, p_category text DEFAULT NULL::text, p_listing_type text DEFAULT NULL::text, p_is_free boolean DEFAULT NULL::boolean, p_is_wanted boolean DEFAULT NULL::boolean, p_condition text DEFAULT NULL::text, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_layer text DEFAULT NULL::text, p_trust_only boolean DEFAULT false, p_search text DEFAULT NULL::text, p_created_after timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_distance double precision DEFAULT NULL::double precision, p_cursor_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 31) RETURNS TABLE(id uuid, user_id uuid, title text, description text, price numeric, is_free boolean, category text, subcategory text, condition text, quantity integer, status text, media_urls text[], media_types text[], location_name text, latitude double precision, longitude double precision, location_precision text, visibility_scope text, meetup_preference text, delivery_available boolean, tags text[], view_count integer, save_count integer, message_count integer, layer text, listing_type text, home_id uuid, is_address_attached boolean, quality_score integer, context_tags text[], is_wanted boolean, budget_max numeric, expires_at timestamp with time zone, created_at timestamp with time zone, updated_at timestamp with time zone, distance_meters double precision)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_ref geography;
BEGIN
  v_ref := ST_SetSRID(ST_MakePoint(p_ref_lng, p_ref_lat), 4326)::geography;

  RETURN QUERY
  SELECT
    l.id,
    l.user_id,
    l.title,
    l.description,
    l.price,
    l.is_free,
    l.category::text,
    l.subcategory,
    l.condition::text,
    l.quantity,
    l.status::text,
    l.media_urls,
    l.media_types,
    l.location_name,
    l.latitude,
    l.longitude,
    l.location_precision::text,
    l.visibility_scope::text,
    l.meetup_preference,
    l.delivery_available,
    l.tags,
    l.view_count,
    l.save_count,
    l.message_count,
    l.layer::text,
    l.listing_type::text,
    l.home_id,
    l.is_address_attached,
    l.quality_score::integer,
    l.context_tags,
    l.is_wanted,
    l.budget_max,
    l.expires_at,
    l.created_at,
    l.updated_at,
    ST_Distance(
      ST_SetSRID(ST_MakePoint(l.longitude, l.latitude), 4326)::geography,
      v_ref
    ) AS distance_meters
  FROM "Listing" l
  WHERE l.status = 'active'
    AND l.archived_at IS NULL
    AND l.latitude  IS NOT NULL
    AND l.longitude IS NOT NULL
    -- Bounding box
    AND l.latitude  >= p_south
    AND l.latitude  <= p_north
    AND l.longitude >= p_west
    AND l.longitude <= p_east
    -- Expiry
    AND (l.expires_at IS NULL OR l.expires_at > now())
    -- Optional filters (cast enum columns to text — params are text)
    AND (p_category     IS NULL OR l.category::text     = p_category)
    AND (p_listing_type IS NULL OR l.listing_type::text = p_listing_type)
    AND (p_is_free      IS NULL OR l.is_free      = p_is_free)
    AND (p_is_wanted    IS NULL OR l.is_wanted    = p_is_wanted)
    AND (p_condition    IS NULL OR l.condition::text    = p_condition)
    AND (p_min_price    IS NULL OR l.price        >= p_min_price)
    AND (p_max_price    IS NULL OR l.price        <= p_max_price)
    AND (p_layer        IS NULL OR l.layer::text       = p_layer)
    AND (NOT p_trust_only       OR l.is_address_attached = true)
    AND (p_created_after IS NULL OR l.created_at >= p_created_after)
    -- Full-text search
    AND (p_search IS NULL OR l.search_vector @@ websearch_to_tsquery('english', p_search))
    -- Keyset cursor: (distance_meters, id) ascending
    AND (
      p_cursor_distance IS NULL
      OR ST_Distance(
           ST_SetSRID(ST_MakePoint(l.longitude, l.latitude), 4326)::geography,
           v_ref
         ) > p_cursor_distance
      OR (
           ST_Distance(
             ST_SetSRID(ST_MakePoint(l.longitude, l.latitude), 4326)::geography,
             v_ref
           ) = p_cursor_distance
           AND l.id > p_cursor_id
         )
    )
  ORDER BY distance_meters ASC, l.id ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.browse_listings_by_distance(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_ref_lat double precision, p_ref_lng double precision, p_category text, p_listing_type text, p_is_free boolean, p_is_wanted boolean, p_condition text, p_min_price numeric, p_max_price numeric, p_layer text, p_trust_only boolean, p_search text, p_created_after timestamp with time zone, p_cursor_distance double precision, p_cursor_id uuid, p_limit integer) OWNER TO postgres;

