--
-- Name: claim_inventory_slot(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.claim_inventory_slot(p_home_id uuid, p_layer text, p_max_count integer DEFAULT 10) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_count int;
  v_max   int;
BEGIN
  -- Try to lock the existing row
  SELECT active_count, max_count
    INTO v_count, v_max
    FROM "ListingInventorySlot"
   WHERE home_id = p_home_id AND layer = p_layer::public.listing_layer
     FOR UPDATE;

  IF NOT FOUND THEN
    -- No slot row yet — insert one with active_count = 1
    INSERT INTO "ListingInventorySlot" (home_id, layer, active_count, max_count)
    VALUES (p_home_id, p_layer::public.listing_layer, 1, p_max_count)
    ON CONFLICT (home_id, layer)
    DO UPDATE SET active_count = "ListingInventorySlot".active_count + 1,
                  updated_at   = now()
    WHERE "ListingInventorySlot".active_count < "ListingInventorySlot".max_count
    RETURNING active_count INTO v_count;

    -- If the ON CONFLICT path ran but the WHERE failed, v_count is null → cap hit
    IF v_count IS NULL THEN
      RETURN false;
    END IF;
    RETURN true;
  END IF;

  -- Row exists and is locked — check cap
  IF v_count >= v_max THEN
    RETURN false;
  END IF;

  UPDATE "ListingInventorySlot"
     SET active_count = active_count + 1,
         updated_at   = now()
   WHERE home_id = p_home_id AND layer = p_layer::public.listing_layer;

  RETURN true;
END;
$$;


ALTER FUNCTION public.claim_inventory_slot(p_home_id uuid, p_layer text, p_max_count integer) OWNER TO postgres;

