--
-- Name: count_nearby_seeded_businesses(double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.count_nearby_seeded_businesses(p_lat double precision, p_lng double precision, p_radius_meters double precision DEFAULT 8047) RETURNS TABLE(category text, cnt bigint)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    sb."category",
    COUNT(*) AS cnt
  FROM "public"."SeededBusiness" sb
  WHERE sb."is_active" = true
    AND ST_DWithin(
      ST_SetSRID(ST_MakePoint(sb."longitude", sb."latitude"), 4326)::geography,
      ST_SetSRID(ST_MakePoint(p_lng, p_lat), 4326)::geography,
      p_radius_meters
    )
  GROUP BY sb."category"
  ORDER BY cnt DESC;
$$;


