--
-- Name: count_neighbors_within(double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.count_neighbors_within(center_lat double precision, center_lng double precision, radius_meters integer DEFAULT 1609) RETURNS integer
    LANGUAGE sql STABLE
    AS $$
  SELECT count(DISTINCT ho.user_id)::integer
  FROM "HomeOccupancy" ho
  JOIN "Home" h ON h.id = ho.home_id
  WHERE ho.is_active = true
    AND h.location IS NOT NULL
    AND ST_DWithin(
          h.location,
          ST_SetSRID(ST_MakePoint(center_lng, center_lat), 4326)::geography,
          radius_meters
        );
$$;


ALTER FUNCTION public.count_neighbors_within(center_lat double precision, center_lng double precision, radius_meters integer) OWNER TO postgres;

--
-- Name: create_business_full(text, text, text, text, text[], text, text, text, uuid, text, text, text, text, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_business_full(p_username text, p_name text, p_email text, p_business_type text, p_categories text[], p_description text, p_public_phone text, p_website text, p_actor_user_id uuid, p_location_address text DEFAULT NULL::text, p_location_city text DEFAULT NULL::text, p_location_state text DEFAULT NULL::text, p_location_zipcode text DEFAULT NULL::text, p_location_country text DEFAULT 'US'::text, p_location_label text DEFAULT 'Main'::text, p_hours jsonb DEFAULT NULL::jsonb) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_biz_user_id uuid;
  v_location_id uuid;
  v_hour jsonb;
BEGIN
  -- Step 1: Create User + BusinessProfile + BusinessTeam + BusinessPrivate + default page
  -- (reuse the existing create_business_transaction logic inline)
  INSERT INTO "User" (username, name, email, account_type)
  VALUES (p_username, p_name, p_email, 'business')
  RETURNING id INTO v_biz_user_id;

  INSERT INTO "BusinessProfile" (
    business_user_id, business_type, categories,
    description, public_email, public_phone, website
  ) VALUES (
    v_biz_user_id, p_business_type, p_categories,
    p_description, p_email, p_public_phone, p_website
  );

  INSERT INTO "BusinessTeam" (business_user_id, user_id, role_base, title, joined_at)
  VALUES (v_biz_user_id, p_actor_user_id, 'owner'::"public"."business_role_base", 'Owner', now());

  INSERT INTO "BusinessPrivate" (business_user_id)
  VALUES (v_biz_user_id);

  INSERT INTO "BusinessPage" (business_user_id, slug, title, is_default, show_in_nav, nav_order)
  VALUES (v_biz_user_id, 'overview', 'Overview', true, true, 0);

  -- Step 2: Optionally create location
  IF p_location_address IS NOT NULL AND p_location_city IS NOT NULL THEN
    INSERT INTO "BusinessLocation" (
      business_user_id, label, is_primary, address, city, state, zipcode, country
    ) VALUES (
      v_biz_user_id, p_location_label, true,
      p_location_address, p_location_city,
      p_location_state, p_location_zipcode, p_location_country
    )
    RETURNING id INTO v_location_id;

    -- Update primary_location_id on profile
    UPDATE "BusinessProfile"
    SET primary_location_id = v_location_id
    WHERE business_user_id = v_biz_user_id;

    -- Step 3: Optionally set hours for this location
    IF p_hours IS NOT NULL AND v_location_id IS NOT NULL THEN
      FOR v_hour IN SELECT * FROM jsonb_array_elements(p_hours)
      LOOP
        INSERT INTO "BusinessHours" (
          location_id, day_of_week, open_time, close_time, is_closed
        ) VALUES (
          v_location_id,
          (v_hour->>'day_of_week')::integer,
          CASE WHEN (v_hour->>'is_closed')::boolean THEN NULL ELSE (v_hour->>'open_time')::time END,
          CASE WHEN (v_hour->>'is_closed')::boolean THEN NULL ELSE (v_hour->>'close_time')::time END,
          COALESCE((v_hour->>'is_closed')::boolean, false)
        );
      END LOOP;
    END IF;
  END IF;

  RETURN json_build_object(
    'business_user_id', v_biz_user_id,
    'location_id', v_location_id
  );
END;
$$;


ALTER FUNCTION public.create_business_full(p_username text, p_name text, p_email text, p_business_type text, p_categories text[], p_description text, p_public_phone text, p_website text, p_actor_user_id uuid, p_location_address text, p_location_city text, p_location_state text, p_location_zipcode text, p_location_country text, p_location_label text, p_hours jsonb) OWNER TO postgres;

--
-- Name: create_business_transaction(text, text, text, text, text[], text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_business_transaction(p_username text, p_name text, p_email text, p_business_type text, p_categories text[], p_description text, p_public_phone text, p_website text, p_actor_user_id uuid) RETURNS json
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_biz_user_id uuid;
BEGIN
  -- Step 1: Create the business User row
  INSERT INTO "User" (username, name, email, account_type)
  VALUES (p_username, p_name, p_email, 'business')
  RETURNING id INTO v_biz_user_id;

  -- Step 2: Create the BusinessProfile
  INSERT INTO "BusinessProfile" (
    business_user_id, business_type, categories,
    description, public_email, public_phone, website
  ) VALUES (
    v_biz_user_id, p_business_type, p_categories,
    p_description, p_email, p_public_phone, p_website
  );

  -- Step 3: Create the BusinessTeam entry (owner)
  INSERT INTO "BusinessTeam" (business_user_id, user_id, role_base, title, joined_at)
  VALUES (v_biz_user_id, p_actor_user_id, 'owner'::"public"."business_role_base", 'Owner', now());

  -- Step 4: Create the BusinessPrivate shell (for later legal/tax info)
  INSERT INTO "BusinessPrivate" (business_user_id)
  VALUES (v_biz_user_id);

  -- Step 5: Create the default Overview page
  INSERT INTO "BusinessPage" (business_user_id, slug, title, is_default, show_in_nav, nav_order)
  VALUES (v_biz_user_id, 'overview', 'Overview', true, true, 0);

  -- If ANY insert above fails, Postgres rolls back the entire function automatically
  RETURN json_build_object('business_user_id', v_biz_user_id);
END;
$$;


ALTER FUNCTION public.create_business_transaction(p_username text, p_name text, p_email text, p_business_type text, p_categories text[], p_description text, p_public_phone text, p_website text, p_actor_user_id uuid) OWNER TO postgres;

--
-- Name: decrement_comment_count(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.decrement_comment_count() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  UPDATE "Post"
  SET comment_count = GREATEST(comment_count - 1, 0)
  WHERE id = OLD.post_id;
  
  RETURN OLD;
END;
$$;


ALTER FUNCTION public.decrement_comment_count() OWNER TO postgres;

--
-- Name: detect_trust_anomalies(timestamp with time zone, timestamp with time zone, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.detect_trust_anomalies(p_lookback_date timestamp with time zone, p_new_home_date timestamp with time zone, p_growth_threshold integer DEFAULT 5, p_limit integer DEFAULT 100) RETURNS TABLE(business_user_id uuid, growth_count bigint, new_home_count bigint)
    LANGUAGE plpgsql STABLE
    AS $_$
BEGIN
  RETURN QUERY
  SELECT
    g.accepted_by AS business_user_id,
    COUNT(DISTINCT g.id)::BIGINT AS growth_count,
    COUNT(DISTINCT CASE
      WHEN origin_home.created_at >= p_new_home_date THEN g.origin_home_id
    END)::BIGINT AS new_home_count
  FROM "Gig" g
  JOIN "Home" origin_home ON origin_home.id = g.origin_home_id
  WHERE g.owner_confirmed_at >= p_lookback_date
    AND g.status IN ('completed', 'reviewed')
    AND g.payment_status IN ('captured_hold', 'transfer_scheduled', 'transfer_pending', 'transferred')
    AND g.price >= 1000  -- $10 minimum (cents)
    AND g.origin_home_id IS NOT NULL
    -- Only count from verified homes
    AND EXISTS (
      SELECT 1 FROM "HomeOccupancy" ho
      WHERE ho.home_id = g.origin_home_id
        AND ho.is_active = true
        AND ho.role_base NOT IN ('guest')
    )
  GROUP BY g.accepted_by
  HAVING COUNT(DISTINCT g.id) > p_growth_threshold
     AND COUNT(DISTINCT CASE
           WHEN origin_home.created_at >= p_new_home_date THEN g.origin_home_id
         END) >= 3  -- At least 3 from new homes
  ORDER BY growth_count DESC
  LIMIT p_limit;
END;
$_$;


ALTER FUNCTION public.detect_trust_anomalies(p_lookback_date timestamp with time zone, p_new_home_date timestamp with time zone, p_growth_threshold integer, p_limit integer) OWNER TO postgres;

--
-- Name: enforce_local_profile_account_search_visibility(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_local_profile_account_search_visibility() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  account_visibility text;
BEGIN
  SELECT ups."search_visibility"::text
  INTO account_visibility
  FROM "public"."UserPrivacySettings" ups
  WHERE ups."user_id" = NEW."user_id";

  IF account_visibility IS NOT NULL
     AND "public"."identity_search_visibility_rank"(account_visibility)
       < "public"."identity_search_visibility_rank"(NEW."search_visibility") THEN
    NEW."search_visibility" = account_visibility;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.enforce_local_profile_account_search_visibility() OWNER TO postgres;

--
-- Name: enforce_mail_update_columns(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.enforce_mail_update_columns() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  if current_user = 'service_role' or current_user = 'postgres' then
    return new;
  end if;

  -- Allowed changes for normal users: viewed, viewed_at, archived, starred
  if (new.viewed is distinct from old.viewed)
     or (new.viewed_at is distinct from old.viewed_at)
     or (new.archived is distinct from old.archived)
     or (new.starred is distinct from old.starred) then
    -- ensure all other fields are unchanged
    if (new.recipient_user_id is distinct from old.recipient_user_id)
       or (new.recipient_home_id is distinct from old.recipient_home_id)
       or (new.sender_user_id is distinct from old.sender_user_id)
       or (new.sender_business_name is distinct from old.sender_business_name)
       or (new.sender_address is distinct from old.sender_address)
       or (new.type is distinct from old.type)
       or (new.subject is distinct from old.subject)
       or (new.content is distinct from old.content)
       or (new.attachments is distinct from old.attachments)
       or (new.payout_amount is distinct from old.payout_amount)
       or (new.payout_status is distinct from old.payout_status)
       or (new.payout_at is distinct from old.payout_at)
       or (new.category is distinct from old.category)
       or (new.tags is distinct from old.tags)
       or (new.priority is distinct from old.priority)
       or (new.expires_at is distinct from old.expires_at)
       or (new.created_at is distinct from old.created_at) then
      raise exception 'Only viewed/viewed_at/archived/starred may be updated by recipients';
    end if;

    return new;
  end if;

  -- No other updates allowed
  raise exception 'No editable columns in Mail for non-service users';
end $$;


ALTER FUNCTION public.enforce_mail_update_columns() OWNER TO postgres;

--
-- Name: find_businesses_in_bounds(double precision, double precision, double precision, double precision, text[], boolean, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_businesses_in_bounds(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_categories text[] DEFAULT NULL::text[], p_open_now_only boolean DEFAULT false, p_limit integer DEFAULT 500) RETURNS TABLE(business_user_id uuid, username character varying, name character varying, profile_picture_url text, latitude double precision, longitude double precision, categories text[], business_type text, average_rating numeric, review_count integer, completed_gigs bigint, is_open_now boolean, is_new_business boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bounds geography;
BEGIN
  -- Build bounding box envelope for spatial query
  v_bounds := ST_SetSRID(
    ST_MakeEnvelope(p_west, p_south, p_east, p_north),
    4326
  )::geography;

  RETURN QUERY
  SELECT
    u.id AS business_user_id,
    u.username,
    u.name,
    u.profile_picture_url,
    ST_Y(bl.location::geometry) AS latitude,
    ST_X(bl.location::geometry) AS longitude,
    bp.categories,
    bp.business_type,
    u.average_rating,
    u.review_count,

    -- Completed gigs count (for pin tier: 0=small, 1-9=medium, 10+=large)
    (SELECT COUNT(*) FROM "Gig" g WHERE g.accepted_by = u.id AND g.status = 'completed') AS completed_gigs,

    -- Open-now check (timezone-aware with special hours override)
    CASE WHEN bl.timezone IS NOT NULL THEN
      COALESCE(
        -- Special hours override for today
        (
          SELECT
            CASE WHEN bsh.is_closed THEN FALSE
              WHEN bsh.open_time IS NULL OR bsh.close_time IS NULL THEN TRUE
              WHEN bsh.close_time < bsh.open_time THEN
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bsh.open_time
                OR (NOW() AT TIME ZONE bl.timezone)::TIME <= bsh.close_time
              ELSE
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bsh.open_time
                AND (NOW() AT TIME ZONE bl.timezone)::TIME <= bsh.close_time
            END
          FROM "BusinessSpecialHours" bsh
          WHERE bsh.location_id = bl.id
            AND bsh.date = (NOW() AT TIME ZONE bl.timezone)::DATE
          LIMIT 1
        ),
        -- Regular hours for today
        (
          SELECT
            CASE WHEN bh.is_closed THEN FALSE
              WHEN bh.open_time IS NULL OR bh.close_time IS NULL THEN TRUE
              WHEN bh.close_time < bh.open_time THEN
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bh.open_time
                OR (NOW() AT TIME ZONE bl.timezone)::TIME <= bh.close_time
              ELSE
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bh.open_time
                AND (NOW() AT TIME ZONE bl.timezone)::TIME <= bh.close_time
            END
          FROM "BusinessHours" bh
          WHERE bh.location_id = bl.id
            AND bh.day_of_week = EXTRACT(DOW FROM NOW() AT TIME ZONE bl.timezone)::INT
          LIMIT 1
        ),
        NULL
      )
    ELSE NULL
    END AS is_open_now,

    -- New business flag (< 3 completed gigs AND profile < 30 days old)
    (
      (SELECT COUNT(*) FROM "Gig" g WHERE g.accepted_by = u.id AND g.status = 'completed') < 3
      AND bp.created_at > NOW() - INTERVAL '30 days'
    ) AS is_new_business

  FROM "User" u
  JOIN "BusinessProfile" bp ON bp.business_user_id = u.id
  JOIN "BusinessLocation" bl ON bl.business_user_id = u.id
    AND bl.is_primary = true
    AND bl.is_active = true
  WHERE u.account_type = 'business'
    AND bp.is_published = true
    AND bl.location IS NOT NULL
    -- Bounding box filter
    AND ST_Intersects(bl.location, v_bounds)
    -- Category filter (optional)
    AND (p_categories IS NULL OR bp.categories && p_categories)
    -- Open-now filter (optional, applied in WHERE for perf)
    AND (
      NOT p_open_now_only
      OR bl.timezone IS NULL
      OR COALESCE(
        (
          SELECT
            CASE WHEN bsh2.is_closed THEN FALSE
              WHEN bsh2.open_time IS NULL OR bsh2.close_time IS NULL THEN TRUE
              WHEN bsh2.close_time < bsh2.open_time THEN
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bsh2.open_time
                OR (NOW() AT TIME ZONE bl.timezone)::TIME <= bsh2.close_time
              ELSE
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bsh2.open_time
                AND (NOW() AT TIME ZONE bl.timezone)::TIME <= bsh2.close_time
            END
          FROM "BusinessSpecialHours" bsh2
          WHERE bsh2.location_id = bl.id
            AND bsh2.date = (NOW() AT TIME ZONE bl.timezone)::DATE
          LIMIT 1
        ),
        (
          SELECT
            CASE WHEN bh2.is_closed THEN FALSE
              WHEN bh2.open_time IS NULL OR bh2.close_time IS NULL THEN TRUE
              WHEN bh2.close_time < bh2.open_time THEN
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bh2.open_time
                OR (NOW() AT TIME ZONE bl.timezone)::TIME <= bh2.close_time
              ELSE
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bh2.open_time
                AND (NOW() AT TIME ZONE bl.timezone)::TIME <= bh2.close_time
            END
          FROM "BusinessHours" bh2
          WHERE bh2.location_id = bl.id
            AND bh2.day_of_week = EXTRACT(DOW FROM NOW() AT TIME ZONE bl.timezone)::INT
          LIMIT 1
        ),
        TRUE  -- If no hours data, treat as open (don't filter out)
      ) = TRUE
    )
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.find_businesses_in_bounds(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_categories text[], p_open_now_only boolean, p_limit integer) OWNER TO postgres;

--
-- Name: find_businesses_nearby(double precision, double precision, integer, uuid, text[], numeric, integer, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_businesses_nearby(p_center_lat double precision, p_center_lon double precision, p_radius_meters integer DEFAULT 8047, p_viewer_home_id uuid DEFAULT NULL::uuid, p_categories text[] DEFAULT NULL::text[], p_rating_min numeric DEFAULT NULL::numeric, p_limit integer DEFAULT 200, p_entity_types text[] DEFAULT NULL::text[]) RETURNS TABLE(business_user_id uuid, username character varying, name character varying, profile_picture_url text, average_rating numeric, review_count integer, categories text[], description text, business_type text, logo_file_id uuid, banner_file_id uuid, avg_response_minutes integer, profile_created_at timestamp with time zone, location_id uuid, primary_address text, primary_city text, primary_state text, location_timezone text, distance_meters integer, neighbor_count bigint, completed_gigs bigint, profile_completeness integer, last_activity_at timestamp with time zone, is_open_now boolean, accepts_gigs boolean, verification_status character varying, founding_badge boolean, founding_benefit_expires_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_center geography;
  v_viewer_location geography;
BEGIN
  -- Build center point for distance calculation
  v_center := ST_SetSRID(ST_MakePoint(p_center_lon, p_center_lat), 4326)::geography;

  -- Resolve viewer home location for neighbor trust count
  IF p_viewer_home_id IS NOT NULL THEN
    SELECT h.location INTO v_viewer_location
    FROM "Home" h
    WHERE h.id = p_viewer_home_id;
  END IF;

  RETURN QUERY
  SELECT
    u.id AS business_user_id,
    u.username,
    u.name,
    u.profile_picture_url,
    u.average_rating,
    u.review_count,
    bp.categories,
    bp.description,
    bp.business_type,
    bp.logo_file_id,
    bp.banner_file_id,
    bp.avg_response_minutes,
    bp.created_at AS profile_created_at,
    bl.id AS location_id,
    bl.address AS primary_address,
    bl.city AS primary_city,
    bl.state AS primary_state,
    bl.timezone AS location_timezone,
    CAST(ST_Distance(bl.location, v_center) AS INT) AS distance_meters,

    -- Neighbor trust count (with gaming protections)
    CASE WHEN v_viewer_location IS NOT NULL THEN
      (
        SELECT COUNT(DISTINCT g.origin_home_id)
        FROM "Gig" g
        JOIN "Home" oh ON oh.id = g.origin_home_id
        JOIN "HomeOccupancy" ho ON ho.home_id = oh.id
          AND ho.is_active = true
          AND (ho.role_base IS NULL OR ho.role_base != 'guest')
        WHERE g.accepted_by = u.id
          AND g.status = 'completed'
          AND g.price >= 10
          AND g.payment_status IN ('captured_hold','transfer_scheduled','transfer_pending','transferred')
          AND g.origin_home_id IS NOT NULL
          AND oh.location IS NOT NULL
          AND ST_DWithin(oh.location, v_viewer_location, p_radius_meters)
          AND (
            EXISTS (SELECT 1 FROM "HomeOwnershipClaim" hoc WHERE hoc.home_id = oh.id AND hoc.state = 'approved')
            OR EXISTS (SELECT 1 FROM "HomeResidencyClaim" hrc WHERE hrc.home_id = oh.id AND hrc.status = 'verified')
          )
          AND NOT EXISTS (
            SELECT 1 FROM "Payment" p
            WHERE p.gig_id = g.id
              AND p.payment_status IN ('disputed','refunded','refunded_full','refunded_partial')
          )
      )
    ELSE 0
    END AS neighbor_count,

    -- Completed gigs (for new-business check)
    (SELECT COUNT(*) FROM "Gig" g WHERE g.accepted_by = u.id AND g.status = 'completed') AS completed_gigs,

    -- Profile completeness: read from stored column instead of computing inline
    bp.profile_completeness,

    -- Last activity: most recent completed gig or post
    GREATEST(
      (SELECT MAX(g2.created_at) FROM "Gig" g2 WHERE g2.accepted_by = u.id AND g2.status = 'completed'),
      (SELECT MAX(po.created_at) FROM "Post" po WHERE po.user_id = u.id)
    ) AS last_activity_at,

    -- Open-now: checks special hours override, then regular hours, handles overnight
    CASE WHEN bl.timezone IS NOT NULL THEN
      COALESCE(
        -- Special hours for today (override)
        (
          SELECT
            CASE WHEN bsh.is_closed THEN FALSE
              WHEN bsh.open_time IS NULL OR bsh.close_time IS NULL THEN TRUE
              WHEN bsh.close_time < bsh.open_time THEN
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bsh.open_time
                OR (NOW() AT TIME ZONE bl.timezone)::TIME <= bsh.close_time
              ELSE
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bsh.open_time
                AND (NOW() AT TIME ZONE bl.timezone)::TIME <= bsh.close_time
            END
          FROM "BusinessSpecialHours" bsh
          WHERE bsh.location_id = bl.id
            AND bsh.date = (NOW() AT TIME ZONE bl.timezone)::DATE
          LIMIT 1
        ),
        -- Regular hours for today
        (
          SELECT
            CASE WHEN bh.is_closed THEN FALSE
              WHEN bh.open_time IS NULL OR bh.close_time IS NULL THEN TRUE
              WHEN bh.close_time < bh.open_time THEN
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bh.open_time
                OR (NOW() AT TIME ZONE bl.timezone)::TIME <= bh.close_time
              ELSE
                (NOW() AT TIME ZONE bl.timezone)::TIME >= bh.open_time
                AND (NOW() AT TIME ZONE bl.timezone)::TIME <= bh.close_time
            END
          FROM "BusinessHours" bh
          WHERE bh.location_id = bl.id
            AND bh.day_of_week = EXTRACT(DOW FROM NOW() AT TIME ZONE bl.timezone)::INT
          LIMIT 1
        ),
        NULL  -- no hours data
      )
    ELSE NULL
    END AS is_open_now,

    -- Accepts gig requests: has active team member with gig-capable role
    EXISTS (
      SELECT 1 FROM "BusinessTeam" bt
      WHERE bt.business_user_id = u.id
        AND bt.is_active = true
        AND bt.role_base IN ('owner', 'admin', 'editor', 'staff')
    ) AS accepts_gigs,

    -- Verification status from stored column
    bp.verification_status,

    -- Founding badge fields
    bp.founding_badge,
    bp.founding_benefit_expires_at

  FROM "User" u
  JOIN "BusinessProfile" bp ON bp.business_user_id = u.id
  JOIN "BusinessLocation" bl ON bl.business_user_id = u.id
    AND bl.is_primary = true
    AND bl.is_active = true
  WHERE u.account_type = 'business'
    AND bp.is_published = true
    AND bl.location IS NOT NULL
    AND ST_DWithin(bl.location, v_center, p_radius_meters)
    -- Category filter (array overlap)
    AND (p_categories IS NULL OR bp.categories && p_categories)
    -- Rating minimum filter
    AND (p_rating_min IS NULL OR COALESCE(u.average_rating, 0) >= p_rating_min)
    -- Entity type filter
    AND (p_entity_types IS NULL OR bp.business_type = ANY(p_entity_types))
  ORDER BY ST_Distance(bl.location, v_center) ASC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.find_businesses_nearby(p_center_lat double precision, p_center_lon double precision, p_radius_meters integer, p_viewer_home_id uuid, p_categories text[], p_rating_min numeric, p_limit integer, p_entity_types text[]) OWNER TO postgres;

--
-- Name: find_gigs_by_category_nearby(double precision, double precision, character varying, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_by_category_nearby(user_lat double precision, user_lon double precision, gig_category character varying, radius_meters integer DEFAULT 10000) RETURNS TABLE(id uuid, title character varying, description text, price numeric, deadline timestamp with time zone, user_id uuid, distance_meters integer, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    g.id,
    g.title,
    g.description,
    g.price,
    g.deadline,
    g.user_id,
    CAST(
      ST_Distance(
        g.exact_location,
        ST_Point(user_lon, user_lat)::GEOGRAPHY
      ) AS INT
    ) as distance_meters,
    g.created_at
  FROM "Gig" g
  WHERE 
    g.status = 'open'
    AND g.category = gig_category
    AND g.exact_location IS NOT NULL
    AND ST_Distance(
      g.exact_location,
      ST_Point(user_lon, user_lat)::GEOGRAPHY
    ) <= radius_meters
  ORDER BY distance_meters ASC;
END;
$$;


ALTER FUNCTION public.find_gigs_by_category_nearby(user_lat double precision, user_lon double precision, gig_category character varying, radius_meters integer) OWNER TO postgres;

--
-- Name: find_gigs_in_bounds(double precision, double precision, double precision, double precision, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_in_bounds(min_lat double precision, min_lon double precision, max_lat double precision, max_lon double precision, gig_status character varying DEFAULT 'open'::character varying) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, user_id uuid, status character varying, latitude double precision, longitude double precision, created_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $$
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.user_id,
    g.status,
    ST_Y(g.approx_location::geometry) AS latitude,
    ST_X(g.approx_location::geometry) AS longitude,
    g.created_at
  FROM "Gig" g
  WHERE
    g.status = gig_status
    AND g.approx_location IS NOT NULL
    AND ST_Intersects(
      g.approx_location::geometry,
      ST_MakeEnvelope(min_lon, min_lat, max_lon, max_lat, 4326)
    )
  ORDER BY g.created_at DESC;
$$;


ALTER FUNCTION public.find_gigs_in_bounds(min_lat double precision, min_lon double precision, max_lat double precision, max_lon double precision, gig_status character varying) OWNER TO postgres;

--
-- Name: find_gigs_in_bounds_v2(double precision, double precision, double precision, double precision, character varying, boolean, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_in_bounds_v2(min_lat double precision, min_lon double precision, max_lat double precision, max_lon double precision, gig_status character varying DEFAULT 'open'::character varying, p_include_remote boolean DEFAULT true, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, user_id uuid, status character varying, latitude double precision, longitude double precision, created_at timestamp with time zone, creator_name character varying, creator_username character varying, profile_picture_url text, exact_city text, exact_state text, location_precision public.location_precision, visibility_scope public.visibility_scope, is_urgent boolean, tags text[], items jsonb, scheduled_start timestamp with time zone, attachments text[], is_remote boolean)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bounds geometry;
BEGIN
  v_bounds := ST_MakeEnvelope(min_lon, min_lat, max_lon, max_lat, 4326);

  RETURN QUERY
  -- Spatially bounded gigs (have approx_location within viewport)
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.user_id,
    g.status,
    ST_Y(g.approx_location::geometry) AS latitude,
    ST_X(g.approx_location::geometry) AS longitude,
    g.created_at,
    u.name AS creator_name,
    u.username AS creator_username,
    u.profile_picture_url,
    g.exact_city,
    g.exact_state,
    g.location_precision,
    g.visibility_scope,
    g.is_urgent,
    g.tags,
    g.items,
    g.scheduled_start,
    g.attachments,
    false AS is_remote
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE
    g.status = gig_status
    AND (g.deadline IS NULL OR g.deadline > now())
    AND g.approx_location IS NOT NULL
    AND ST_Intersects(g.approx_location::geometry, v_bounds)
    AND (p_category IS NULL OR g.category = p_category)

  UNION ALL

  -- Remote gigs (no location) — appear in side list only, no map pins
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.user_id,
    g.status,
    NULL::double precision AS latitude,
    NULL::double precision AS longitude,
    g.created_at,
    u.name AS creator_name,
    u.username AS creator_username,
    u.profile_picture_url,
    g.exact_city,
    g.exact_state,
    g.location_precision,
    g.visibility_scope,
    g.is_urgent,
    g.tags,
    g.items,
    g.scheduled_start,
    g.attachments,
    true AS is_remote
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE
    p_include_remote IS TRUE
    AND g.status = gig_status
    AND (g.deadline IS NULL OR g.deadline > now())
    AND g.approx_location IS NULL
    AND (p_category IS NULL OR g.category = p_category)

  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.find_gigs_in_bounds_v2(min_lat double precision, min_lon double precision, max_lat double precision, max_lon double precision, gig_status character varying, p_include_remote boolean, p_category text, p_limit integer) OWNER TO postgres;

--
-- Name: find_gigs_in_bounds_v3(double precision, double precision, double precision, double precision, character varying, boolean, text, integer, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_in_bounds_v3(min_lat double precision, min_lon double precision, max_lat double precision, max_lon double precision, gig_status character varying DEFAULT 'open'::character varying, p_include_remote boolean DEFAULT true, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_pricing_mode text DEFAULT NULL::text, p_pay_unit text DEFAULT NULL::text, p_schedule_pattern text DEFAULT NULL::text, p_service_type text DEFAULT NULL::text, p_is_negotiable boolean DEFAULT NULL::boolean) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, user_id uuid, status character varying, latitude double precision, longitude double precision, created_at timestamp with time zone, creator_name character varying, creator_username character varying, profile_picture_url text, exact_city text, exact_state text, location_precision public.location_precision, visibility_scope public.visibility_scope, is_urgent boolean, tags text[], items jsonb, scheduled_start timestamp with time zone, attachments text[], is_remote boolean, pricing_mode public.pricing_mode, pay_unit public.pay_unit, unit_label text, rate_amount_cents integer, rate_max_amount_cents integer, estimated_units numeric, cap_amount_cents integer, cap_period public.cap_period, is_negotiable boolean, pricing_notes text, schedule_pattern public.schedule_pattern, recurrence jsonb, schedule_start_at timestamp with time zone, schedule_end_at timestamp with time zone, service_type text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bounds geometry;
BEGIN
  v_bounds := ST_MakeEnvelope(min_lon, min_lat, max_lon, max_lat, 4326);

  RETURN QUERY
  -- Spatially bounded gigs
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.user_id,
    g.status,
    ST_Y(g.approx_location::geometry) AS latitude,
    ST_X(g.approx_location::geometry) AS longitude,
    g.created_at,
    u.name AS creator_name,
    u.username AS creator_username,
    u.profile_picture_url,
    g.exact_city,
    g.exact_state,
    g.location_precision,
    g.visibility_scope,
    g.is_urgent,
    g.tags,
    g.items,
    g.scheduled_start,
    g.attachments,
    false AS is_remote,
    g.pricing_mode,
    g.pay_unit,
    g.unit_label,
    g.rate_amount_cents,
    g.rate_max_amount_cents,
    g.estimated_units,
    g.cap_amount_cents,
    g.cap_period,
    g.is_negotiable,
    g.pricing_notes,
    g.schedule_pattern,
    g.recurrence,
    g.schedule_start_at,
    g.schedule_end_at,
    g.service_type
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE
    g.status = gig_status
    AND (g.deadline IS NULL OR g.deadline > now())
    AND g.approx_location IS NOT NULL
    AND ST_Intersects(g.approx_location::geometry, v_bounds)
    AND (p_category IS NULL OR g.category = p_category)
    AND (p_pricing_mode IS NULL OR g.pricing_mode = p_pricing_mode::"public"."pricing_mode")
    AND (p_pay_unit IS NULL OR g.pay_unit = p_pay_unit::"public"."pay_unit")
    AND (p_schedule_pattern IS NULL OR g.schedule_pattern = p_schedule_pattern::"public"."schedule_pattern")
    AND (p_service_type IS NULL OR g.service_type = p_service_type)
    AND (p_is_negotiable IS NULL OR g.is_negotiable = p_is_negotiable)

  UNION ALL

  -- Remote gigs (no location) — appear in side list only, no map pins
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.user_id,
    g.status,
    NULL::double precision AS latitude,
    NULL::double precision AS longitude,
    g.created_at,
    u.name AS creator_name,
    u.username AS creator_username,
    u.profile_picture_url,
    g.exact_city,
    g.exact_state,
    g.location_precision,
    g.visibility_scope,
    g.is_urgent,
    g.tags,
    g.items,
    g.scheduled_start,
    g.attachments,
    true AS is_remote,
    g.pricing_mode,
    g.pay_unit,
    g.unit_label,
    g.rate_amount_cents,
    g.rate_max_amount_cents,
    g.estimated_units,
    g.cap_amount_cents,
    g.cap_period,
    g.is_negotiable,
    g.pricing_notes,
    g.schedule_pattern,
    g.recurrence,
    g.schedule_start_at,
    g.schedule_end_at,
    g.service_type
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE
    p_include_remote IS TRUE
    AND g.status = gig_status
    AND (g.deadline IS NULL OR g.deadline > now())
    AND g.approx_location IS NULL
    AND (p_category IS NULL OR g.category = p_category)
    AND (p_pricing_mode IS NULL OR g.pricing_mode = p_pricing_mode::"public"."pricing_mode")
    AND (p_pay_unit IS NULL OR g.pay_unit = p_pay_unit::"public"."pay_unit")
    AND (p_schedule_pattern IS NULL OR g.schedule_pattern = p_schedule_pattern::"public"."schedule_pattern")
    AND (p_service_type IS NULL OR g.service_type = p_service_type)
    AND (p_is_negotiable IS NULL OR g.is_negotiable = p_is_negotiable)

  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.find_gigs_in_bounds_v3(min_lat double precision, min_lon double precision, max_lat double precision, max_lon double precision, gig_status character varying, p_include_remote boolean, p_category text, p_limit integer, p_pricing_mode text, p_pay_unit text, p_schedule_pattern text, p_service_type text, p_is_negotiable boolean) OWNER TO postgres;

--
-- Name: find_gigs_nearby(double precision, double precision, integer, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_nearby(user_lat double precision, user_lon double precision, radius_meters integer DEFAULT 5000, gig_status character varying DEFAULT 'open'::character varying) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, deadline timestamp with time zone, estimated_duration double precision, user_id uuid, status character varying, accepted_by uuid, created_at timestamp with time zone, distance_meters integer, creator_name character varying, creator_username character varying)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.deadline,
    g.estimated_duration,
    g.user_id,
    g.status,
    g.accepted_by,
    g.created_at,
    CAST(
      ST_Distance(
        g.exact_location,
        ST_Point(user_lon, user_lat)::GEOGRAPHY
      ) AS INT
    ) as distance_meters,
    u.name as creator_name,
    u.username as creator_username
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE 
    g.status = gig_status
    AND g.exact_location IS NOT NULL
    AND ST_Distance(
      g.exact_location,
      ST_Point(user_lon, user_lat)::GEOGRAPHY
    ) <= radius_meters
  ORDER BY distance_meters ASC;
END;
$$;


ALTER FUNCTION public.find_gigs_nearby(user_lat double precision, user_lon double precision, radius_meters integer, gig_status character varying) OWNER TO postgres;

--
-- Name: find_gigs_nearby_v2(double precision, double precision, integer, text, numeric, numeric, text, text, integer, integer, boolean, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_nearby_v2(user_lat double precision, user_lon double precision, p_radius_meters integer DEFAULT 40234, p_category text DEFAULT NULL::text, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_include_remote boolean DEFAULT true, gig_status character varying DEFAULT 'open'::character varying) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, deadline timestamp with time zone, estimated_duration double precision, user_id uuid, status character varying, accepted_by uuid, created_at timestamp with time zone, distance_meters integer, creator_name character varying, creator_username character varying, profile_picture_url text, exact_city text, exact_state text, approx_latitude double precision, approx_longitude double precision, location_precision public.location_precision, visibility_scope public.visibility_scope, is_urgent boolean, tags text[], items jsonb, scheduled_start timestamp with time zone, attachments text[])
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_point geography;
BEGIN
  v_point := ST_SetSRID(ST_MakePoint(user_lon, user_lat), 4326)::geography;

  RETURN QUERY
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.deadline,
    g.estimated_duration,
    g.user_id,
    g.status,
    g.accepted_by,
    g.created_at,
    CASE
      WHEN g.exact_location IS NOT NULL THEN
        CAST(ST_Distance(g.exact_location, v_point) AS INT)
      ELSE NULL
    END AS distance_meters,
    u.name AS creator_name,
    u.username AS creator_username,
    u.profile_picture_url,
    g.exact_city,
    g.exact_state,
    CASE
      WHEN g.approx_location IS NOT NULL THEN ST_Y(g.approx_location::geometry)
      ELSE NULL
    END AS approx_latitude,
    CASE
      WHEN g.approx_location IS NOT NULL THEN ST_X(g.approx_location::geometry)
      ELSE NULL
    END AS approx_longitude,
    g.location_precision,
    g.visibility_scope,
    g.is_urgent,
    g.tags,
    g.items,
    g.scheduled_start,
    g.attachments
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE
    g.status = gig_status
    -- Exclude gigs whose deadline has already passed
    AND (g.deadline IS NULL OR g.deadline > now())
    -- Location filter: include remote gigs (NULL location) OR gigs within radius
    AND (
      (p_include_remote IS TRUE AND g.exact_location IS NULL)
      OR ST_DWithin(g.exact_location, v_point, p_radius_meters)
    )
    -- Optional filters
    AND (p_category IS NULL OR g.category = p_category)
    AND (p_min_price IS NULL OR g.price >= p_min_price)
    AND (p_max_price IS NULL OR g.price <= p_max_price)
    AND (p_search IS NULL OR g.title ILIKE '%' || p_search || '%' OR g.description ILIKE '%' || p_search || '%')
  ORDER BY
    CASE WHEN p_sort = 'newest' THEN g.created_at END DESC,
    CASE WHEN p_sort = 'price_asc' THEN g.price END ASC,
    CASE WHEN p_sort = 'price_desc' THEN g.price END DESC,
    CASE WHEN p_sort = 'distance' AND g.exact_location IS NOT NULL THEN ST_Distance(g.exact_location, v_point) END ASC NULLS LAST,
    g.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.find_gigs_nearby_v2(user_lat double precision, user_lon double precision, p_radius_meters integer, p_category text, p_min_price numeric, p_max_price numeric, p_search text, p_sort text, p_limit integer, p_offset integer, p_include_remote boolean, gig_status character varying) OWNER TO postgres;

--
-- Name: find_gigs_nearby_v3(double precision, double precision, integer, text, numeric, numeric, text, text, integer, integer, boolean, character varying, text, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_gigs_nearby_v3(user_lat double precision, user_lon double precision, p_radius_meters integer DEFAULT 40234, p_category text DEFAULT NULL::text, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_include_remote boolean DEFAULT true, gig_status character varying DEFAULT 'open'::character varying, p_pricing_mode text DEFAULT NULL::text, p_pay_unit text DEFAULT NULL::text, p_schedule_pattern text DEFAULT NULL::text, p_service_type text DEFAULT NULL::text, p_is_negotiable boolean DEFAULT NULL::boolean) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, deadline timestamp with time zone, estimated_duration double precision, user_id uuid, status character varying, accepted_by uuid, created_at timestamp with time zone, distance_meters integer, creator_name character varying, creator_username character varying, profile_picture_url text, exact_city text, exact_state text, approx_latitude double precision, approx_longitude double precision, location_precision public.location_precision, visibility_scope public.visibility_scope, is_urgent boolean, tags text[], items jsonb, scheduled_start timestamp with time zone, attachments text[], pricing_mode public.pricing_mode, pay_unit public.pay_unit, unit_label text, rate_amount_cents integer, rate_max_amount_cents integer, estimated_units numeric, cap_amount_cents integer, cap_period public.cap_period, is_negotiable boolean, pricing_notes text, schedule_pattern public.schedule_pattern, recurrence jsonb, schedule_start_at timestamp with time zone, schedule_end_at timestamp with time zone, service_type text)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_point geography;
BEGIN
  v_point := ST_SetSRID(ST_MakePoint(user_lon, user_lat), 4326)::geography;

  RETURN QUERY
  SELECT
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.deadline,
    g.estimated_duration,
    g.user_id,
    g.status,
    g.accepted_by,
    g.created_at,
    CASE
      WHEN g.exact_location IS NOT NULL THEN
        CAST(ST_Distance(g.exact_location, v_point) AS INT)
      ELSE NULL
    END AS distance_meters,
    u.name AS creator_name,
    u.username AS creator_username,
    u.profile_picture_url,
    g.exact_city,
    g.exact_state,
    CASE
      WHEN g.approx_location IS NOT NULL THEN ST_Y(g.approx_location::geometry)
      ELSE NULL
    END AS approx_latitude,
    CASE
      WHEN g.approx_location IS NOT NULL THEN ST_X(g.approx_location::geometry)
      ELSE NULL
    END AS approx_longitude,
    g.location_precision,
    g.visibility_scope,
    g.is_urgent,
    g.tags,
    g.items,
    g.scheduled_start,
    g.attachments,
    g.pricing_mode,
    g.pay_unit,
    g.unit_label,
    g.rate_amount_cents,
    g.rate_max_amount_cents,
    g.estimated_units,
    g.cap_amount_cents,
    g.cap_period,
    g.is_negotiable,
    g.pricing_notes,
    g.schedule_pattern,
    g.recurrence,
    g.schedule_start_at,
    g.schedule_end_at,
    g.service_type
  FROM "Gig" g
  LEFT JOIN "User" u ON g.user_id = u.id
  WHERE
    g.status = gig_status
    AND (g.deadline IS NULL OR g.deadline > now())
    AND (
      (p_include_remote IS TRUE AND g.exact_location IS NULL)
      OR ST_DWithin(g.exact_location, v_point, p_radius_meters)
    )
    AND (p_category IS NULL OR g.category = p_category)
    -- Price filter prefers the structured rate when the unit is hourly; otherwise
    -- falls back to the legacy g.price (back-filled deterministically in A4).
    AND (
      p_min_price IS NULL
      OR CASE
           WHEN p_pay_unit = 'hour' AND g.rate_amount_cents IS NOT NULL
             THEN (g.rate_amount_cents::numeric / 100.0) >= p_min_price
           ELSE g.price >= p_min_price
         END
    )
    AND (
      p_max_price IS NULL
      OR CASE
           WHEN p_pay_unit = 'hour' AND g.rate_amount_cents IS NOT NULL
             THEN (g.rate_amount_cents::numeric / 100.0) <= p_max_price
           ELSE g.price <= p_max_price
         END
    )
    AND (p_search IS NULL OR g.title ILIKE '%' || p_search || '%' OR g.description ILIKE '%' || p_search || '%')
    -- Structured filters
    AND (p_pricing_mode IS NULL OR g.pricing_mode = p_pricing_mode::"public"."pricing_mode")
    AND (p_pay_unit IS NULL OR g.pay_unit = p_pay_unit::"public"."pay_unit")
    AND (p_schedule_pattern IS NULL OR g.schedule_pattern = p_schedule_pattern::"public"."schedule_pattern")
    AND (p_service_type IS NULL OR g.service_type = p_service_type)
    AND (p_is_negotiable IS NULL OR g.is_negotiable = p_is_negotiable)
  ORDER BY
    CASE WHEN p_sort = 'newest' THEN g.created_at END DESC,
    CASE WHEN p_sort = 'price_asc' THEN g.price END ASC,
    CASE WHEN p_sort = 'price_desc' THEN g.price END DESC,
    CASE WHEN p_sort = 'rate_asc'  THEN g.rate_amount_cents END ASC NULLS LAST,
    CASE WHEN p_sort = 'rate_desc' THEN g.rate_amount_cents END DESC NULLS LAST,
    CASE WHEN p_sort = 'cap_asc'   THEN g.cap_amount_cents END ASC NULLS LAST,
    CASE WHEN p_sort = 'cap_desc'  THEN g.cap_amount_cents END DESC NULLS LAST,
    CASE WHEN p_sort = 'distance' AND g.exact_location IS NOT NULL THEN ST_Distance(g.exact_location, v_point) END ASC NULLS LAST,
    g.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.find_gigs_nearby_v3(user_lat double precision, user_lon double precision, p_radius_meters integer, p_category text, p_min_price numeric, p_max_price numeric, p_search text, p_sort text, p_limit integer, p_offset integer, p_include_remote boolean, gig_status character varying, p_pricing_mode text, p_pay_unit text, p_schedule_pattern text, p_service_type text, p_is_negotiable boolean) OWNER TO postgres;

--
-- Name: find_listings_in_bounds(double precision, double precision, double precision, double precision, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_listings_in_bounds(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, title text, price numeric, is_free boolean, category public.listing_category, media_urls text[], latitude double precision, longitude double precision, location_precision public.location_precision, created_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_bounds geometry;
BEGIN
    v_bounds := ST_MakeEnvelope(p_west, p_south, p_east, p_north, 4326);

    RETURN QUERY
    SELECT
        l.id,
        l.title,
        l.price,
        l.is_free,
        l.category,
        l.media_urls,
        -- For approx_area, add random offset to lat/lng (privacy blur)
        CASE
            WHEN l.location_precision = 'exact_place' THEN l.latitude
            WHEN l.location_precision = 'approx_area' THEN l.latitude + (random() - 0.5) * 0.005
            ELSE NULL
        END,
        CASE
            WHEN l.location_precision = 'exact_place' THEN l.longitude
            WHEN l.location_precision = 'approx_area' THEN l.longitude + (random() - 0.5) * 0.005
            ELSE NULL
        END,
        l.location_precision,
        l.created_at
    FROM "Listing" l
    WHERE
        l.status = 'active'
        AND l.location IS NOT NULL
        AND l.location_precision != 'none'
        AND l.location_precision != 'neighborhood_only'
        AND ST_Intersects(l.location::geometry, v_bounds)
        AND (p_category IS NULL OR l.category::text = p_category)
    ORDER BY l.created_at DESC
    LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.find_listings_in_bounds(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_category text, p_limit integer) OWNER TO postgres;

--
-- Name: find_listings_in_bounds_v2(double precision, double precision, double precision, double precision, text, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_listings_in_bounds_v2(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_layer text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_limit integer DEFAULT 100) RETURNS TABLE(id uuid, title text, price numeric, is_free boolean, category public.listing_category, media_urls text[], latitude double precision, longitude double precision, location_precision public.location_precision, created_at timestamp with time zone, layer public.listing_layer, listing_type public.listing_type, is_address_attached boolean, is_wanted boolean, context_tags text[])
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_bounds geometry;
BEGIN
  v_bounds := ST_MakeEnvelope(p_west, p_south, p_east, p_north, 4326);

  RETURN QUERY
  SELECT
    l.id,
    l.title,
    l.price,
    l.is_free,
    l.category,
    l.media_urls,
    -- Privacy blur for approx_area locations
    CASE
      WHEN l.location_precision = 'exact_place' THEN l.latitude
      WHEN l.location_precision = 'approx_area' THEN l.latitude + (random() - 0.5) * 0.005
      ELSE NULL
    END,
    CASE
      WHEN l.location_precision = 'exact_place' THEN l.longitude
      WHEN l.location_precision = 'approx_area' THEN l.longitude + (random() - 0.5) * 0.005
      ELSE NULL
    END,
    l.location_precision,
    l.created_at,
    -- New columns
    l.layer,
    l.listing_type,
    l.is_address_attached,
    l.is_wanted,
    l.context_tags
  FROM "Listing" l
  WHERE
    l.status = 'active'
    AND l.location IS NOT NULL
    AND l.location_precision != 'none'
    AND l.location_precision != 'neighborhood_only'
    AND ST_Intersects(l.location::geometry, v_bounds)
    AND (p_layer IS NULL OR l.layer::text = p_layer)
    AND (p_category IS NULL OR l.category::text = p_category)
    -- Exclude expired
    AND (l.expires_at IS NULL OR l.expires_at > now())
  ORDER BY l.created_at DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.find_listings_in_bounds_v2(p_south double precision, p_west double precision, p_north double precision, p_east double precision, p_layer text, p_category text, p_limit integer) OWNER TO postgres;

--
-- Name: find_listings_nearby(double precision, double precision, integer, integer, integer, text, numeric, numeric, boolean, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_listings_nearby(p_latitude double precision, p_longitude double precision, p_radius_meters integer DEFAULT 16000, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_category text DEFAULT NULL::text, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_is_free boolean DEFAULT NULL::boolean, p_condition text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, user_profile_picture text, title text, description text, price numeric, is_free boolean, category public.listing_category, subcategory text, condition public.listing_condition, status public.listing_status, media_urls text[], media_types text[], location_name text, location_precision public.location_precision, tags text[], view_count integer, save_count integer, created_at timestamp with time zone, distance_meters integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_point geography;
BEGIN
    v_point := ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography;

    RETURN QUERY
    SELECT
        l.id,
        l.user_id,
        u.username,
        u.name AS user_name,
        u.profile_picture_url AS user_profile_picture,
        l.title,
        l.description,
        l.price,
        l.is_free,
        l.category,
        l.subcategory,
        l.condition,
        l.status,
        l.media_urls,
        l.media_types,
        l.location_name,
        l.location_precision,
        l.tags,
        l.view_count,
        l.save_count,
        l.created_at,
        CASE
            WHEN l.location IS NOT NULL THEN
                CAST(ST_Distance(l.location, v_point) AS INT)
            ELSE NULL
        END AS distance_meters
    FROM "Listing" l
    JOIN "User" u ON l.user_id = u.id
    WHERE
        l.status = 'active'
        AND (l.location IS NULL OR ST_DWithin(l.location, v_point, p_radius_meters))
        AND (p_category IS NULL OR l.category::text = p_category)
        AND (p_min_price IS NULL OR l.price >= p_min_price)
        AND (p_max_price IS NULL OR l.price <= p_max_price)
        AND (p_is_free IS NULL OR l.is_free = p_is_free)
        AND (p_condition IS NULL OR l.condition::text = p_condition)
        AND (p_search IS NULL OR l.search_vector @@ plainto_tsquery('english', p_search))
    ORDER BY
        CASE WHEN p_sort = 'newest' THEN l.created_at END DESC,
        CASE WHEN p_sort = 'price_asc' THEN l.price END ASC,
        CASE WHEN p_sort = 'price_desc' THEN l.price END DESC,
        CASE WHEN p_sort = 'distance' AND l.location IS NOT NULL THEN ST_Distance(l.location, v_point) END ASC,
        l.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.find_listings_nearby(p_latitude double precision, p_longitude double precision, p_radius_meters integer, p_limit integer, p_offset integer, p_category text, p_min_price numeric, p_max_price numeric, p_is_free boolean, p_condition text, p_search text, p_sort text) OWNER TO postgres;

--
-- Name: find_listings_nearby_v2(double precision, double precision, integer, integer, integer, text, text, text, numeric, numeric, boolean, text, text, text, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_listings_nearby_v2(p_latitude double precision, p_longitude double precision, p_radius_meters integer DEFAULT 16000, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_layer text DEFAULT NULL::text, p_listing_type text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_min_price numeric DEFAULT NULL::numeric, p_max_price numeric DEFAULT NULL::numeric, p_is_free boolean DEFAULT NULL::boolean, p_condition text DEFAULT NULL::text, p_search text DEFAULT NULL::text, p_sort text DEFAULT 'newest'::text, p_trust_only boolean DEFAULT false, p_is_wanted boolean DEFAULT NULL::boolean) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, user_profile_picture text, title text, description text, price numeric, is_free boolean, category public.listing_category, subcategory text, condition public.listing_condition, status public.listing_status, media_urls text[], media_types text[], location_name text, location_precision public.location_precision, tags text[], view_count integer, save_count integer, created_at timestamp with time zone, distance_meters integer, layer public.listing_layer, listing_type public.listing_type, home_id uuid, is_address_attached boolean, quality_score numeric, context_tags text[], is_wanted boolean, budget_max numeric, expires_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_point geography;
BEGIN
  v_point := ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography;

  RETURN QUERY
  SELECT
    l.id,
    l.user_id,
    u.username,
    u.name AS user_name,
    u.profile_picture_url AS user_profile_picture,
    l.title,
    l.description,
    l.price,
    l.is_free,
    l.category,
    l.subcategory,
    l.condition,
    l.status,
    l.media_urls,
    l.media_types,
    l.location_name,
    l.location_precision,
    l.tags,
    l.view_count,
    l.save_count,
    l.created_at,
    CASE
      WHEN l.location IS NOT NULL THEN
        CAST(ST_Distance(l.location, v_point) AS INT)
      ELSE NULL
    END AS distance_meters,
    -- New columns
    l.layer,
    l.listing_type,
    l.home_id,
    l.is_address_attached,
    l.quality_score,
    l.context_tags,
    l.is_wanted,
    l.budget_max,
    l.expires_at
  FROM "Listing" l
  JOIN "User" u ON l.user_id = u.id
  WHERE
    l.status = 'active'
    AND (l.location IS NULL OR ST_DWithin(l.location, v_point, p_radius_meters))
    AND (p_layer IS NULL OR l.layer::text = p_layer)
    AND (p_listing_type IS NULL OR l.listing_type::text = p_listing_type)
    AND (p_category IS NULL OR l.category::text = p_category)
    AND (p_min_price IS NULL OR l.price >= p_min_price)
    AND (p_max_price IS NULL OR l.price <= p_max_price)
    AND (p_is_free IS NULL OR l.is_free = p_is_free)
    AND (p_condition IS NULL OR l.condition::text = p_condition)
    AND (p_search IS NULL OR l.search_vector @@ plainto_tsquery('english', p_search))
    AND (NOT p_trust_only OR l.is_address_attached = true)
    AND (p_is_wanted IS NULL OR l.is_wanted = p_is_wanted)
    -- Exclude expired listings
    AND (l.expires_at IS NULL OR l.expires_at > now())
  ORDER BY
    CASE WHEN p_sort = 'newest' THEN l.created_at END DESC,
    CASE WHEN p_sort = 'price_asc' THEN l.price END ASC,
    CASE WHEN p_sort = 'price_desc' THEN l.price END DESC,
    CASE WHEN p_sort = 'distance' AND l.location IS NOT NULL THEN ST_Distance(l.location, v_point) END ASC,
    l.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.find_listings_nearby_v2(p_latitude double precision, p_longitude double precision, p_radius_meters integer, p_limit integer, p_offset integer, p_layer text, p_listing_type text, p_category text, p_min_price numeric, p_max_price numeric, p_is_free boolean, p_condition text, p_search text, p_sort text, p_trust_only boolean, p_is_wanted boolean) OWNER TO postgres;

--
-- Name: find_nearest_activity_center(double precision, double precision, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.find_nearest_activity_center(p_center_lat double precision, p_center_lon double precision, p_content_type text DEFAULT 'gig'::text) RETURNS TABLE(latitude double precision, longitude double precision)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  IF p_content_type = 'gig' THEN
    RETURN QUERY
      SELECT
        ST_Y(g.approx_location::geometry)::double precision AS latitude,
        ST_X(g.approx_location::geometry)::double precision AS longitude
      FROM "Gig" g
      WHERE g.approx_location IS NOT NULL
        AND g.status = 'open'
      ORDER BY g.approx_location <-> ST_SetSRID(ST_MakePoint(p_center_lon, p_center_lat), 4326)::geography
      LIMIT 1;

  ELSIF p_content_type = 'business' THEN
    RETURN QUERY
      SELECT
        ST_Y(bl.location::geometry)::double precision AS latitude,
        ST_X(bl.location::geometry)::double precision AS longitude
      FROM "BusinessLocation" bl
      WHERE bl.location IS NOT NULL
        AND bl.is_primary = true
      ORDER BY bl.location <-> ST_SetSRID(ST_MakePoint(p_center_lon, p_center_lat), 4326)::geography
      LIMIT 1;

  ELSIF p_content_type = 'post' THEN
    RETURN QUERY
      SELECT
        ST_Y(p.location::geometry)::double precision AS latitude,
        ST_X(p.location::geometry)::double precision AS longitude
      FROM "Post" p
      WHERE p.location IS NOT NULL
        AND p.is_archived = false
      ORDER BY p.location <-> ST_SetSRID(ST_MakePoint(p_center_lon, p_center_lat), 4326)::geography
      LIMIT 1;

  ELSIF p_content_type = 'listing' THEN
    RETURN QUERY
      SELECT
        ST_Y(l.location::geometry)::double precision AS latitude,
        ST_X(l.location::geometry)::double precision AS longitude
      FROM "Listing" l
      WHERE l.location IS NOT NULL
        AND l.status = 'active'
      ORDER BY l.location <-> ST_SetSRID(ST_MakePoint(p_center_lon, p_center_lat), 4326)::geography
      LIMIT 1;
  END IF;
END;
$$;


ALTER FUNCTION public.find_nearest_activity_center(p_center_lat double precision, p_center_lon double precision, p_content_type text) OWNER TO postgres;

--
-- Name: get_building_trust_count(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_building_trust_count(p_business_user_id uuid, p_parent_home_id uuid, p_category text DEFAULT NULL::text) RETURNS bigint
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_count BIGINT;
BEGIN
  SELECT COUNT(DISTINCT g.origin_home_id) INTO v_count
  FROM "Gig" g
  JOIN "Home" origin_home ON origin_home.id = g.origin_home_id
  JOIN "HomeOccupancy" ho
    ON ho.home_id = origin_home.id
    AND ho.is_active = true
    AND (ho.role_base IS NULL OR ho.role_base != 'guest')
  WHERE g.accepted_by = p_business_user_id
    AND g.status = 'completed'
    AND g.price >= 10
    AND g.payment_status IN ('captured_hold', 'transfer_scheduled', 'transfer_pending', 'transferred')
    AND g.origin_home_id IS NOT NULL
    AND origin_home.parent_home_id = p_parent_home_id
    -- Same verified address gate
    AND (
      EXISTS (
        SELECT 1 FROM "HomeOwnershipClaim" hoc
        WHERE hoc.home_id = origin_home.id AND hoc.state = 'approved'
      )
      OR EXISTS (
        SELECT 1 FROM "HomeResidencyClaim" hrc
        WHERE hrc.home_id = origin_home.id AND hrc.status = 'verified'
      )
    )
    -- Same rate limit
    AND NOT EXISTS (
      SELECT 1 FROM "Gig" g2
      WHERE g2.origin_home_id = g.origin_home_id
        AND g2.accepted_by = g.accepted_by
        AND g2.category = g.category
        AND g2.id != g.id
        AND g2.status = 'completed'
        AND g2.created_at > g.created_at - INTERVAL '30 days'
        AND g2.created_at < g.created_at
    )
    -- Same payment check
    AND NOT EXISTS (
      SELECT 1 FROM "Payment" p
      WHERE p.gig_id = g.id
        AND p.payment_status IN ('disputed', 'refunded', 'refunded_full', 'refunded_partial')
    )
    AND (p_category IS NULL OR g.category = p_category);

  RETURN v_count;
END;
$$;


ALTER FUNCTION public.get_building_trust_count(p_business_user_id uuid, p_parent_home_id uuid, p_category text) OWNER TO postgres;

--
-- Name: get_endorsement_count(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_endorsement_count(p_business_user_id uuid, p_viewer_home_id uuid, p_radius_meters integer DEFAULT 8047, p_category text DEFAULT NULL::text) RETURNS TABLE(endorsement_count bigint, by_category jsonb)
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_viewer_location  geography;
BEGIN
  -- Get viewer home location
  SELECT h.location INTO v_viewer_location
  FROM "Home" h
  WHERE h.id = p_viewer_home_id;

  IF v_viewer_location IS NULL THEN
    RETURN QUERY SELECT 0::BIGINT, '[]'::JSONB;
    RETURN;
  END IF;

  RETURN QUERY
  WITH eligible_endorsements AS (
    SELECT
      e.id,
      e.category
    FROM "NeighborEndorsement" e
    JOIN "Home" endorser_home ON endorser_home.id = e.endorser_home_id
    -- Only endorsements from within radius
    WHERE e.business_user_id = p_business_user_id
      AND (p_category IS NULL OR e.category = p_category)
      AND ST_DWithin(endorser_home.location, v_viewer_location, p_radius_meters)
      -- Verified occupancy gate: endorser must have active, non-guest occupancy
      AND EXISTS (
        SELECT 1 FROM "HomeOccupancy" ho
        WHERE ho.home_id = e.endorser_home_id
          AND ho.user_id = e.endorser_user_id
          AND ho.is_active = true
          AND ho.role_base NOT IN ('guest')
      )
      -- Minimum home age: 14 days (anti-gaming)
      AND endorser_home.created_at <= (now() - INTERVAL '14 days')
  )
  SELECT
    COUNT(*)::BIGINT,
    COALESCE(
      (SELECT jsonb_agg(jsonb_build_object('category', cat, 'count', cnt))
       FROM (
         SELECT category AS cat, COUNT(*) AS cnt
         FROM eligible_endorsements
         GROUP BY category
         ORDER BY cnt DESC
       ) sub),
      '[]'::JSONB
    )
  FROM eligible_endorsements;
END;
$$;


ALTER FUNCTION public.get_endorsement_count(p_business_user_id uuid, p_viewer_home_id uuid, p_radius_meters integer, p_category text) OWNER TO postgres;

--
-- Name: get_full_home_profile(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_full_home_profile(p_home_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'home', row_to_json(h.*),
    'members', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'user_id', ho.user_id,
        'role', ho.role,
        'is_active', ho.is_active,
        'can_manage_home', ho.can_manage_home,
        'can_manage_finance', ho.can_manage_finance,
        'can_manage_tasks', ho.can_manage_tasks,
        'name', u.name,
        'username', u.username,
        'profile_picture_url', u.profile_picture_url
      )), '[]'::jsonb)
      FROM "HomeOccupancy" ho
      JOIN "User" u ON u.id = ho.user_id
      WHERE ho.home_id = p_home_id AND ho.is_active = true
    ),
    'media', (
      SELECT coalesce(jsonb_agg(jsonb_build_object(
        'id', hm.id,
        'file_id', hm.file_id,
        'url', f.file_url,
        'category', hm.media_category,
        'is_primary', hm.is_primary
      ) ORDER BY hm.is_primary DESC, hm.display_order), '[]'::jsonb)
      FROM "HomeMedia" hm
      JOIN "File" f ON f.id = hm.file_id
      WHERE hm.home_id = p_home_id AND f.is_deleted = false
    ),
    'reputation', (
      SELECT row_to_json(hr.*)
      FROM "HomeReputation" hr WHERE hr.home_id = p_home_id
    ),
    'open_issues_count', (
      SELECT count(*) FROM "HomeIssue"
      WHERE home_id = p_home_id AND status IN ('open','scheduled','in_progress')
    ),
    'pending_bills_count', (
      SELECT count(*) FROM "HomeBill"
      WHERE home_id = p_home_id AND status IN ('due','overdue')
    )
  ) INTO v_result
  FROM "Home" h WHERE h.id = p_home_id;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_full_home_profile(p_home_id uuid) OWNER TO postgres;

--
-- Name: get_gigs_by_distance(double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_gigs_by_distance(user_lat double precision, user_lon double precision, limit_count integer DEFAULT 20) RETURNS TABLE(id uuid, title character varying, description text, price numeric, category character varying, deadline timestamp with time zone, user_id uuid, status character varying, created_at timestamp with time zone, distance_meters integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    g.id,
    g.title,
    g.description,
    g.price,
    g.category,
    g.deadline,
    g.user_id,
    g.status,
    g.created_at,
    CAST(
      ST_Distance(
        g.exact_location,
        ST_Point(user_lon, user_lat)::GEOGRAPHY
      ) AS INT
    ) as distance_meters
  FROM "Gig" g
  WHERE g.status = 'open' AND g.exact_location IS NOT NULL
  ORDER BY distance_meters ASC
  LIMIT limit_count;
END;
$$;


ALTER FUNCTION public.get_gigs_by_distance(user_lat double precision, user_lon double precision, limit_count integer) OWNER TO postgres;

--
-- Name: get_home_profile_with_media(uuid, character varying); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_home_profile_with_media(p_home_id uuid, p_visibility character varying DEFAULT 'public'::character varying) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'home', row_to_json(h.*),
    'photos', (
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', hm.id,
          'fileId', hm.file_id,
          'url', f.file_url,
          'category', hm.media_category,
          'title', hm.title,
          'description', hm.description,
          'isPrimary', hm.is_primary,
          'thumbnails', (
            SELECT jsonb_object_agg(
              ft.size_name,
              ft.file_url
            )
            FROM "FileThumbnail" ft
            WHERE ft.file_id = f.id
          )
        )
        ORDER BY hm.is_primary DESC, hm.display_order, hm.created_at
      )
      FROM "HomeMedia" hm
      JOIN "File" f ON hm.file_id = f.id
      WHERE hm.home_id = p_home_id
        AND (p_visibility = 'private' OR hm.visibility = 'public')
        AND f.is_deleted = FALSE
    )
  ) INTO v_result
  FROM "Home" h
  WHERE h.id = p_home_id;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_home_profile_with_media(p_home_id uuid, p_visibility character varying) OWNER TO postgres;

--
-- Name: get_listing_carousel(double precision, double precision, integer, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_listing_carousel(p_latitude double precision, p_longitude double precision, p_radius_meters integer DEFAULT 8047, p_layer text DEFAULT NULL::text, p_limit integer DEFAULT 10) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, user_profile_picture text, title text, price numeric, is_free boolean, category public.listing_category, condition public.listing_condition, media_urls text[], location_name text, location_precision public.location_precision, created_at timestamp with time zone, distance_meters integer, layer public.listing_layer, listing_type public.listing_type, home_id uuid, is_address_attached boolean, quality_score numeric, context_tags text[], is_wanted boolean, budget_max numeric, expires_at timestamp with time zone, carousel_score numeric)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_point geography;
BEGIN
  v_point := ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography;

  RETURN QUERY
  WITH scored AS (
    SELECT
      l.id,
      l.user_id,
      u.username,
      u.name AS user_name,
      u.profile_picture_url AS user_profile_picture,
      l.title,
      l.price,
      l.is_free,
      l.category,
      l.condition,
      l.media_urls,
      l.location_name,
      l.location_precision,
      l.created_at,
      CASE
        WHEN l.location IS NOT NULL THEN CAST(ST_Distance(l.location, v_point) AS INT)
        ELSE NULL
      END AS distance_meters,
      l.layer,
      l.listing_type,
      l.home_id,
      l.is_address_attached,
      l.quality_score,
      l.context_tags,
      l.is_wanted,
      l.budget_max,
      l.expires_at,
      -- Composite ranking score
      (
        -- DistanceScore (0-1): closer = higher, exponential decay
        0.30 * CASE
          WHEN l.location IS NOT NULL THEN
            GREATEST(1.0 - (ST_Distance(l.location, v_point)::numeric / p_radius_meters::numeric), 0.0)
          ELSE 0.5
        END
        -- RecencyScore (0-1): newer = higher, 30-day decay
        + 0.20 * (1.0 - LEAST(EXTRACT(EPOCH FROM (now() - l.created_at)) / 2592000.0, 1.0))
        -- TrustScore (0-1): attached = 1.0
        + 0.20 * CASE WHEN l.is_address_attached = true THEN 1.0 ELSE 0.0 END
        -- QualityScore (0-1): from stored quality_score (0-10 scale)
        + 0.15 * COALESCE(l.quality_score, 0) / 10.0
        -- ReputationScore (0-1): placeholder until review aggregation exists per user
        + 0.15 * 0.5
      )::numeric AS carousel_score,
      -- For diversity: row_number per seller
      ROW_NUMBER() OVER (PARTITION BY l.user_id ORDER BY l.created_at DESC) AS seller_rank,
      -- For diversity: row_number per category
      ROW_NUMBER() OVER (PARTITION BY l.category ORDER BY l.created_at DESC) AS category_rank
    FROM "Listing" l
    JOIN "User" u ON l.user_id = u.id
    WHERE
      l.status = 'active'
      AND l.location IS NOT NULL
      AND ST_DWithin(l.location, v_point, p_radius_meters)
      AND (p_layer IS NULL OR l.layer::text = p_layer)
      AND (l.expires_at IS NULL OR l.expires_at > now())
  ),
  -- Apply diversity: max 1 per seller, max 3 per category
  diverse AS (
    SELECT *
    FROM scored
    WHERE seller_rank <= 1 AND category_rank <= 3
  )
  SELECT
    d.id,
    d.user_id,
    d.username,
    d.user_name,
    d.user_profile_picture,
    d.title,
    d.price,
    d.is_free,
    d.category,
    d.condition,
    d.media_urls,
    d.location_name,
    d.location_precision,
    d.created_at,
    d.distance_meters,
    d.layer,
    d.listing_type,
    d.home_id,
    d.is_address_attached,
    d.quality_score,
    d.context_tags,
    d.is_wanted,
    d.budget_max,
    d.expires_at,
    d.carousel_score
  FROM diverse d
  ORDER BY d.carousel_score DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_listing_carousel(p_latitude double precision, p_longitude double precision, p_radius_meters integer, p_layer text, p_limit integer) OWNER TO postgres;

--
-- Name: get_neighbor_trust_count(uuid, uuid, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_neighbor_trust_count(p_business_user_id uuid, p_viewer_home_id uuid, p_radius_meters integer DEFAULT 1609, p_category text DEFAULT NULL::text) RETURNS TABLE(neighbor_count bigint, home_density bigint)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_viewer_location geography;
BEGIN
  -- Resolve viewer home location
  SELECT h.location INTO v_viewer_location
  FROM "Home" h
  WHERE h.id = p_viewer_home_id;

  -- If viewer has no location, return zeros
  IF v_viewer_location IS NULL THEN
    RETURN QUERY SELECT 0::BIGINT, 0::BIGINT;
    RETURN;
  END IF;

  RETURN QUERY
  WITH trust_gigs AS (
    SELECT DISTINCT g.origin_home_id
    FROM "Gig" g
    JOIN "Home" origin_home ON origin_home.id = g.origin_home_id
    JOIN "HomeOccupancy" ho
      ON ho.home_id = origin_home.id
      AND ho.is_active = true
      AND (ho.role_base IS NULL OR ho.role_base != 'guest')
    WHERE g.accepted_by = p_business_user_id
      AND g.status = 'completed'
      AND g.price >= 10                              -- price floor (anti-spam)
      AND g.payment_status IN ('captured_hold', 'transfer_scheduled', 'transfer_pending', 'transferred')  -- real payment only
      AND g.origin_home_id IS NOT NULL
      -- Verified address gate: home must have approved ownership or verified residency
      AND (
        EXISTS (
          SELECT 1 FROM "HomeOwnershipClaim" hoc
          WHERE hoc.home_id = origin_home.id
            AND hoc.state = 'approved'
        )
        OR EXISTS (
          SELECT 1 FROM "HomeResidencyClaim" hrc
          WHERE hrc.home_id = origin_home.id
            AND hrc.status = 'verified'
        )
      )
      -- Rate limit: 1 trust-counting completion per (home, provider, category) per 30 days
      -- Only count the earliest gig in each 30-day window
      AND NOT EXISTS (
        SELECT 1 FROM "Gig" g2
        WHERE g2.origin_home_id = g.origin_home_id
          AND g2.accepted_by = g.accepted_by
          AND g2.category = g.category
          AND g2.id != g.id
          AND g2.status = 'completed'
          AND g2.created_at > g.created_at - INTERVAL '30 days'
          AND g2.created_at < g.created_at
      )
      -- No disputed or refunded payments for this gig
      AND NOT EXISTS (
        SELECT 1 FROM "Payment" p
        WHERE p.gig_id = g.id
          AND p.payment_status IN ('disputed', 'refunded', 'refunded_full', 'refunded_partial')
      )
      -- Optional category filter
      AND (p_category IS NULL OR g.category = p_category)
      -- Proximity: origin home within radius of viewer home
      AND origin_home.location IS NOT NULL
      AND ST_DWithin(origin_home.location, v_viewer_location, p_radius_meters)
  )
  SELECT
    (SELECT COUNT(*) FROM trust_gigs)::BIGINT AS neighbor_count,
    (
      SELECT COUNT(DISTINCT ho2.home_id)
      FROM "HomeOccupancy" ho2
      JOIN "Home" h2 ON h2.id = ho2.home_id
      WHERE ho2.is_active = true
        AND h2.location IS NOT NULL
        AND ST_DWithin(h2.location, v_viewer_location, p_radius_meters)
    )::BIGINT AS home_density;
END;
$$;


ALTER FUNCTION public.get_neighbor_trust_count(p_business_user_id uuid, p_viewer_home_id uuid, p_radius_meters integer, p_category text) OWNER TO postgres;

--
-- Name: get_neighborhood_feed(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_neighborhood_feed(p_user_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, content text, media_urls text[], post_type character varying, like_count integer, comment_count integer, created_at timestamp with time zone, user_has_liked boolean, distance_meters integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  WITH user_location AS (
    SELECT h.location
    FROM "HomeOccupancy" ho
    JOIN "Home" h ON ho.home_id = h.id
    WHERE ho.user_id = p_user_id
    LIMIT 1
  )
  SELECT 
    p.id,
    p.user_id,
    u.username,
    u.name as user_name,
    p.content,
    p.media_urls,
    p.post_type,
    p.like_count,
    p.comment_count,
    p.created_at,
    EXISTS(
      SELECT 1 FROM "PostLike" pl 
      WHERE pl.post_id = p.id AND pl.user_id = p_user_id
    ) as user_has_liked,
    CASE 
      WHEN p.home_id IS NOT NULL AND (SELECT location FROM user_location) IS NOT NULL THEN
        CAST(
          ST_Distance(
            h.location,
            (SELECT location FROM user_location)
          ) AS INT
        )
      ELSE NULL
    END as distance_meters
  FROM "Post" p
  JOIN "User" u ON p.user_id = u.id
  LEFT JOIN "Home" h ON p.home_id = h.id
  WHERE 
    p.is_archived = FALSE
    AND p.visibility IN ('public', 'neighborhood')
    AND (
      -- Posts from same city
      u.city = (SELECT viewer.city FROM "User" viewer WHERE viewer.id = p_user_id)
      OR
      -- Posts from users they follow
      EXISTS(
        SELECT 1 FROM "UserFollow" uf 
        WHERE uf.follower_id = p_user_id AND uf.following_id = p.user_id
      )
    )
  ORDER BY p.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_neighborhood_feed(p_user_id uuid, p_limit integer, p_offset integer) OWNER TO postgres;

--
-- Name: get_neighborhood_feed(uuid, integer, integer, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_neighborhood_feed(p_user_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_post_type text DEFAULT NULL::text, p_radius_meters integer DEFAULT 16000) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, user_first_name character varying, user_profile_picture text, user_city character varying, user_state character varying, content text, media_urls text[], media_types text[], post_type character varying, visibility character varying, like_count integer, comment_count integer, share_count integer, is_pinned boolean, is_edited boolean, created_at timestamp with time zone, user_has_liked boolean, home_id uuid, home_address character varying, home_city character varying, post_latitude double precision, post_longitude double precision, post_location_name text, distance_meters integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_location geography;
  v_user_city     text;
BEGIN
  -- Resolve the caller's location from their primary home
  SELECT h.location, u.city
  INTO v_user_location, v_user_city
  FROM "User" u
  LEFT JOIN "HomeOccupancy" ho ON ho.user_id = u.id
  LEFT JOIN "Home" h ON ho.home_id = h.id AND h.location IS NOT NULL
  WHERE u.id = p_user_id
  LIMIT 1;

  RETURN QUERY
  SELECT
    p.id,
    p.user_id,
    u.username,
    u.name              AS user_name,
    u.first_name        AS user_first_name,
    u.profile_picture_url AS user_profile_picture,
    u.city              AS user_city,
    u.state             AS user_state,
    p.content,
    p.media_urls,
    p.media_types,
    p.post_type,
    p.visibility,
    p.like_count,
    p.comment_count,
    p.share_count,
    p.is_pinned,
    p.is_edited,
    p.created_at,
    EXISTS(
      SELECT 1 FROM "PostLike" pl
      WHERE pl.post_id = p.id AND pl.user_id = p_user_id
    ) AS user_has_liked,
    p.home_id,
    h.address           AS home_address,
    h.city              AS home_city,
    p.latitude          AS post_latitude,
    p.longitude         AS post_longitude,
    p.location_name     AS post_location_name,
    CASE
      WHEN v_user_location IS NOT NULL AND (p.location IS NOT NULL OR h.location IS NOT NULL) THEN
        CAST(ST_Distance(
          COALESCE(p.location, h.location),
          v_user_location
        ) AS INT)
      ELSE NULL
    END AS distance_meters
  FROM "Post" p
  JOIN "User" u ON p.user_id = u.id
  LEFT JOIN "Home" h ON p.home_id = h.id
  WHERE
    p.is_archived = FALSE
    AND p.visibility IN ('public', 'neighborhood')
    -- Post type filter (optional)
    AND (p_post_type IS NULL OR p.post_type::text = p_post_type)
    AND (
      -- Geo proximity: posts within radius
      (
        v_user_location IS NOT NULL
        AND (p.location IS NOT NULL OR h.location IS NOT NULL)
        AND ST_DWithin(
          COALESCE(p.location, h.location),
          v_user_location,
          p_radius_meters
        )
      )
      OR
      -- City fallback: same city (case-insensitive)
      (LOWER(u.city) = LOWER(v_user_city) AND v_user_city IS NOT NULL)
      OR
      -- Following: always show followed users
      EXISTS(
        SELECT 1 FROM "UserFollow" uf
        WHERE uf.follower_id = p_user_id AND uf.following_id = p.user_id
      )
      OR
      -- Own posts
      p.user_id = p_user_id
    )
  ORDER BY
    p.is_pinned DESC,     -- pinned first
    p.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_neighborhood_feed(p_user_id uuid, p_limit integer, p_offset integer, p_post_type text, p_radius_meters integer) OWNER TO postgres;

--
-- Name: get_neighborhood_feed_at(uuid, double precision, double precision, integer, integer, text, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_neighborhood_feed_at(p_user_id uuid, p_latitude double precision, p_longitude double precision, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_post_type text DEFAULT NULL::text, p_radius_meters integer DEFAULT 16000) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, user_first_name character varying, user_profile_picture text, user_city character varying, user_state character varying, content text, media_urls text[], media_types text[], post_type character varying, visibility character varying, like_count integer, comment_count integer, share_count integer, is_pinned boolean, is_edited boolean, created_at timestamp with time zone, user_has_liked boolean, home_id uuid, home_address character varying, home_city character varying, post_latitude double precision, post_longitude double precision, post_location_name text, distance_meters integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_user_location geography;
BEGIN
  -- Build a geography point from the explicit coordinates
  v_user_location := ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography;

  RETURN QUERY
  SELECT
    p.id,
    p.user_id,
    u.username,
    u.name              AS user_name,
    u.first_name        AS user_first_name,
    u.profile_picture_url AS user_profile_picture,
    u.city              AS user_city,
    u.state             AS user_state,
    p.content,
    p.media_urls,
    p.media_types,
    p.post_type,
    p.visibility,
    p.like_count,
    p.comment_count,
    p.share_count,
    p.is_pinned,
    p.is_edited,
    p.created_at,
    EXISTS(
      SELECT 1 FROM "PostLike" pl
      WHERE pl.post_id = p.id AND pl.user_id = p_user_id
    ) AS user_has_liked,
    p.home_id,
    h.address           AS home_address,
    h.city              AS home_city,
    p.latitude          AS post_latitude,
    p.longitude         AS post_longitude,
    p.location_name     AS post_location_name,
    CASE
      WHEN (p.location IS NOT NULL OR h.location IS NOT NULL) THEN
        CAST(ST_Distance(
          COALESCE(p.location, h.location),
          v_user_location
        ) AS INT)
      ELSE NULL
    END AS distance_meters
  FROM "Post" p
  JOIN "User" u ON p.user_id = u.id
  LEFT JOIN "Home" h ON p.home_id = h.id
  WHERE
    p.is_archived = FALSE
    AND p.visibility IN ('public', 'neighborhood')
    -- Post type filter (optional)
    AND (p_post_type IS NULL OR p.post_type::text = p_post_type)
    AND (
      -- Geo proximity: posts within radius of the provided coordinates
      (
        (p.location IS NOT NULL OR h.location IS NOT NULL)
        AND ST_DWithin(
          COALESCE(p.location, h.location),
          v_user_location,
          p_radius_meters
        )
      )
      OR
      -- Following: always show followed users
      EXISTS(
        SELECT 1 FROM "UserFollow" uf
        WHERE uf.follower_id = p_user_id AND uf.following_id = p.user_id
      )
      OR
      -- Own posts
      p.user_id = p_user_id
    )
  ORDER BY
    p.is_pinned DESC,
    p.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_neighborhood_feed_at(p_user_id uuid, p_latitude double precision, p_longitude double precision, p_limit integer, p_offset integer, p_post_type text, p_radius_meters integer) OWNER TO postgres;

--
-- Name: get_neighborhood_feed_v2(uuid, double precision, double precision, integer, integer, text, integer, text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_neighborhood_feed_v2(p_user_id uuid, p_latitude double precision, p_longitude double precision, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0, p_post_type text DEFAULT NULL::text, p_radius_meters integer DEFAULT 16000, p_tags text[] DEFAULT NULL::text[]) RETURNS TABLE(id uuid, user_id uuid, username character varying, user_name character varying, user_first_name character varying, user_profile_picture text, user_city character varying, user_state character varying, title text, content text, media_urls text[], media_types text[], post_type character varying, post_format public.post_format, visibility character varying, visibility_scope public.visibility_scope, location_precision public.location_precision, tags text[], like_count integer, comment_count integer, share_count integer, is_pinned boolean, is_edited boolean, created_at timestamp with time zone, user_has_liked boolean, user_has_saved boolean, home_id uuid, home_city character varying, post_latitude double precision, post_longitude double precision, post_location_name text, distance_meters integer, event_date timestamp with time zone, event_end_date timestamp with time zone, event_venue text, safety_alert_kind public.safety_alert_kind, safety_happened_at timestamp with time zone, deal_expires_at timestamp with time zone, ref_listing_id uuid, ref_task_id uuid)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_location geography;
BEGIN
    v_user_location := ST_SetSRID(ST_MakePoint(p_longitude, p_latitude), 4326)::geography;

    RETURN QUERY
    SELECT
        p.id,
        p.user_id,
        u.username,
        u.name              AS user_name,
        u.first_name        AS user_first_name,
        u.profile_picture_url AS user_profile_picture,
        u.city              AS user_city,
        u.state             AS user_state,
        p.title,
        p.content,
        p.media_urls,
        p.media_types,
        p.post_type,
        p.post_format,
        p.visibility,
        p.visibility_scope,
        p.location_precision,
        p.tags,
        p.like_count,
        p.comment_count,
        p.share_count,
        p.is_pinned,
        p.is_edited,
        p.created_at,
        EXISTS(
            SELECT 1 FROM "PostLike" pl
            WHERE pl.post_id = p.id AND pl.user_id = p_user_id
        ) AS user_has_liked,
        EXISTS(
            SELECT 1 FROM "PostSave" ps
            WHERE ps.post_id = p.id AND ps.user_id = p_user_id
        ) AS user_has_saved,
        p.home_id,
        h.city              AS home_city,
        -- Apply location precision to returned coordinates
        CASE
            WHEN p.location_precision = 'exact_place' THEN p.latitude
            WHEN p.location_precision = 'approx_area' THEN p.latitude + (random() - 0.5) * 0.005
            ELSE NULL
        END AS post_latitude,
        CASE
            WHEN p.location_precision = 'exact_place' THEN p.longitude
            WHEN p.location_precision = 'approx_area' THEN p.longitude + (random() - 0.5) * 0.005
            ELSE NULL
        END AS post_longitude,
        p.location_name     AS post_location_name,
        CASE
            WHEN (p.location IS NOT NULL OR h.location IS NOT NULL) THEN
                CAST(ST_Distance(
                    COALESCE(p.location, h.location),
                    v_user_location
                ) AS INT)
            ELSE NULL
        END AS distance_meters,
        p.event_date,
        p.event_end_date,
        p.event_venue,
        p.safety_alert_kind,
        p.safety_happened_at,
        p.deal_expires_at,
        p.ref_listing_id,
        p.ref_task_id
    FROM "Post" p
    JOIN "User" u ON p.user_id = u.id
    LEFT JOIN "Home" h ON p.home_id = h.id
    WHERE
        p.is_archived = FALSE
        AND p.visibility IN ('public', 'neighborhood', 'city', 'radius')
        AND (p_post_type IS NULL OR p.post_type::text = p_post_type)
        AND (p_tags IS NULL OR p.tags && p_tags)  -- array overlap: has any of the requested tags
        AND (
            -- Geo proximity
            (
                (p.location IS NOT NULL OR h.location IS NOT NULL)
                AND ST_DWithin(
                    COALESCE(p.location, h.location),
                    v_user_location,
                    p_radius_meters
                )
            )
            OR
            -- Following
            EXISTS(
                SELECT 1 FROM "UserFollow" uf
                WHERE uf.follower_id = p_user_id AND uf.following_id = p.user_id
            )
            OR
            -- Own posts
            p.user_id = p_user_id
        )
    ORDER BY
        p.is_pinned DESC,
        p.created_at DESC
    LIMIT p_limit
    OFFSET p_offset;
END;
$$;


ALTER FUNCTION public.get_neighborhood_feed_v2(p_user_id uuid, p_latitude double precision, p_longitude double precision, p_limit integer, p_offset integer, p_post_type text, p_radius_meters integer, p_tags text[]) OWNER TO postgres;

--
-- Name: get_or_create_direct_chat(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_create_direct_chat(p_user_id_1 uuid, p_user_id_2 uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_room_id UUID;
BEGIN
  -- Prevent creating a chat with yourself
  IF p_user_id_1 = p_user_id_2 THEN
    RAISE EXCEPTION 'Cannot create chat with yourself';
  END IF;

  -- Look for an existing direct chat between these two users
  SELECT cp1.room_id INTO v_room_id
  FROM "ChatParticipant" cp1
  JOIN "ChatParticipant" cp2 ON cp1.room_id = cp2.room_id
  JOIN "ChatRoom" r ON r.id = cp1.room_id
  WHERE cp1.user_id = p_user_id_1
    AND cp2.user_id = p_user_id_2
    AND r.type = 'direct'
  LIMIT 1;

  IF v_room_id IS NOT NULL THEN
    -- Reactivate participants if they left
    UPDATE "ChatParticipant"
    SET is_active = true, left_at = NULL
    WHERE room_id = v_room_id
      AND user_id IN (p_user_id_1, p_user_id_2)
      AND is_active = false;

    RETURN v_room_id;
  END IF;

  -- Create a new direct chat room
  INSERT INTO "ChatRoom" (type)
  VALUES ('direct')
  RETURNING id INTO v_room_id;

  -- Add both participants
  INSERT INTO "ChatParticipant" (room_id, user_id, role, is_active)
  VALUES
    (v_room_id, p_user_id_1, 'owner', true),
    (v_room_id, p_user_id_2, 'member', true);

  RETURN v_room_id;
END;
$$;


ALTER FUNCTION public.get_or_create_direct_chat(p_user_id_1 uuid, p_user_id_2 uuid) OWNER TO postgres;

--
-- Name: get_or_create_gig_chat(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_create_gig_chat(p_gig_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
DECLARE
  v_room_id UUID;
  v_gig_title TEXT;
BEGIN
  -- Check if a gig chat room already exists
  SELECT id INTO v_room_id
  FROM "ChatRoom"
  WHERE gig_id = p_gig_id
    AND type = 'gig'
  LIMIT 1;

  -- If found, return it
  IF v_room_id IS NOT NULL THEN
    RETURN v_room_id;
  END IF;

  -- Get gig title for the room name
  SELECT title INTO v_gig_title
  FROM "Gig"
  WHERE id = p_gig_id;

  -- Create a new gig chat room
  INSERT INTO "ChatRoom" (type, gig_id, name)
  VALUES ('gig', p_gig_id, COALESCE('Gig: ' || v_gig_title, 'Gig Chat'))
  RETURNING id INTO v_room_id;

  RETURN v_room_id;
END;
$$;


ALTER FUNCTION public.get_or_create_gig_chat(p_gig_id uuid) OWNER TO postgres;

--
-- Name: get_or_create_home_chat(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_create_home_chat(p_home_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_room_id UUID;
BEGIN
  -- Try to find existing room
  SELECT id INTO v_room_id
  FROM "ChatRoom"
  WHERE home_id = p_home_id AND type = 'home'
  LIMIT 1;
  
  -- Create if doesn't exist
  IF v_room_id IS NULL THEN
    INSERT INTO "ChatRoom" (type, home_id, name)
    VALUES ('home', p_home_id, 'Home Chat')
    RETURNING id INTO v_room_id;
  END IF;
  
  RETURN v_room_id;
END;
$$;


ALTER FUNCTION public.get_or_create_home_chat(p_home_id uuid) OWNER TO postgres;

--
-- Name: get_or_create_user_quota(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_or_create_user_quota(p_user_id uuid) RETURNS TABLE(storage_limit bigint, storage_used bigint, storage_available bigint, file_count integer, max_files integer)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  -- Create quota if doesn't exist
  INSERT INTO "FileQuota" (user_id)
  VALUES (p_user_id)
  ON CONFLICT (user_id) DO NOTHING;
  
  -- Return quota info
  RETURN QUERY
  SELECT 
    q.storage_limit,
    q.storage_used,
    q.storage_limit - q.storage_used as storage_available,
    q.file_count,
    q.max_files
  FROM "FileQuota" q
  WHERE q.user_id = p_user_id;
END;
$$;


ALTER FUNCTION public.get_or_create_user_quota(p_user_id uuid) OWNER TO postgres;

