CREATE FUNCTION public.get_room_previews(p_room_ids uuid[]) RETURNS TABLE(room_id uuid, message text, created_at timestamp with time zone, deleted boolean, type text, attachments jsonb)
    LANGUAGE sql STABLE
    AS $$
  SELECT DISTINCT ON (m.room_id)
    m.room_id,
    m.message,
    m.created_at,
    m.deleted,
    m.type,
    m.attachments
  FROM "ChatMessage" m
  WHERE m.room_id = ANY(p_room_ids)
    AND m.deleted = false
  ORDER BY m.room_id, m.created_at DESC, m.id DESC;
$$;


