--
-- Name: get_seeder_tapering_metrics(double precision, double precision, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_seeder_tapering_metrics(region_lat double precision, region_lng double precision, region_radius_meters integer) RETURNS TABLE(avg_daily_posts numeric, active_posters integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_center geography;
BEGIN
  v_center := ST_SetSRID(ST_MakePoint(region_lng, region_lat), 4326)::geography;

  RETURN QUERY
  SELECT
    -- Average organic posts per day over the last 7 days
    COALESCE(
      ROUND(COUNT(*)::numeric / 7, 2),
      0
    ) AS avg_daily_posts,
    -- Distinct non-curator users who posted in the last 7 days
    COALESCE(
      COUNT(DISTINCT p."user_id")::integer,
      0
    ) AS active_posters
  FROM "public"."Post" p
  JOIN "public"."User" u ON p."user_id" = u."id"
  WHERE u."account_type" != 'curator'
    AND p."created_at" > now() - interval '7 days'
    AND p."archived_at" IS NULL
    AND (
      -- Primary: use the geography column if available
      (p."location" IS NOT NULL AND ST_DWithin(p."location", v_center, region_radius_meters))
      OR
      -- Fallback: use effective_latitude/effective_longitude
      (p."location" IS NULL
       AND p."effective_latitude" IS NOT NULL
       AND p."effective_longitude" IS NOT NULL
       AND ST_DWithin(
         ST_SetSRID(ST_MakePoint(p."effective_longitude", p."effective_latitude"), 4326)::geography,
         v_center,
         region_radius_meters
       ))
    );
END;
$$;


ALTER FUNCTION public.get_seeder_tapering_metrics(region_lat double precision, region_lng double precision, region_radius_meters integer) OWNER TO postgres;

--
-- Name: get_user_business_locations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_business_locations(p_user_id uuid) RETURNS TABLE(location_id uuid, business_name character varying, location_label text, city text, state text, latitude double precision, longitude double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    bl.id          AS location_id,
    u.name         AS business_name,
    bl.label       AS location_label,
    bl.city,
    bl.state,
    CASE WHEN bl.location IS NOT NULL THEN ST_Y(bl.location::geometry) ELSE NULL END AS latitude,
    CASE WHEN bl.location IS NOT NULL THEN ST_X(bl.location::geometry) ELSE NULL END AS longitude
  FROM "BusinessTeam" bt
  JOIN "User" u ON bt.business_user_id = u.id
  JOIN "BusinessLocation" bl ON bl.business_user_id = bt.business_user_id AND bl.is_active = TRUE
  WHERE bt.user_id = p_user_id
    AND bt.is_active = TRUE
  ORDER BY bl.is_primary DESC, bl.sort_order ASC;
END;
$$;


ALTER FUNCTION public.get_user_business_locations(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_user_chat_rooms(uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_chat_rooms(p_user_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, room_type character varying, room_name character varying, description text, gig_id uuid, home_id uuid, is_active boolean, created_at timestamp with time zone, updated_at timestamp with time zone, last_message_at timestamp with time zone, last_message_preview text, unread_count integer, last_read_at timestamp with time zone, role character varying, other_participant_name text, other_participant_username text)
    LANGUAGE plpgsql SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    r.id,
    r.type AS room_type,
    r.name AS room_name,
    r.description,
    r.gig_id,
    r.home_id,
    r.is_active,
    r.created_at,
    r.updated_at,
    -- Use the latest message time, or fall back to room updated_at
    COALESCE(
      (SELECT MAX(cm.created_at) FROM "ChatMessage" cm WHERE cm.room_id = r.id AND cm.deleted = false),
      r.updated_at
    ) AS last_message_at,
    -- Get last message preview
    (
      SELECT LEFT(cm.message, 100)
      FROM "ChatMessage" cm
      WHERE cm.room_id = r.id AND cm.deleted = false
      ORDER BY cm.created_at DESC
      LIMIT 1
    ) AS last_message_preview,
    cp.unread_count,
    cp.last_read_at,
    cp.role,
    -- Get the other participant's name (for direct/gig chats)
    (
      SELECT COALESCE(u.name, u.first_name || ' ' || u.last_name, u.username)
      FROM "ChatParticipant" cp2
      JOIN "User" u ON u.id = cp2.user_id
      WHERE cp2.room_id = r.id
        AND cp2.user_id != p_user_id
        AND cp2.is_active = true
      LIMIT 1
    )::text AS other_participant_name,
    (
      SELECT u.username
      FROM "ChatParticipant" cp2
      JOIN "User" u ON u.id = cp2.user_id
      WHERE cp2.room_id = r.id
        AND cp2.user_id != p_user_id
        AND cp2.is_active = true
      LIMIT 1
    )::text AS other_participant_username
  FROM "ChatParticipant" cp
  JOIN "ChatRoom" r ON r.id = cp.room_id
  WHERE cp.user_id = p_user_id
    AND cp.is_active = true
  ORDER BY COALESCE(
    (SELECT MAX(cm.created_at) FROM "ChatMessage" cm WHERE cm.room_id = r.id AND cm.deleted = false),
    r.updated_at
  ) DESC NULLS LAST
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION public.get_user_chat_rooms(p_user_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_user_earnings(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_earnings(p_user_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH scoped AS (
    SELECT
      payment_status,
      GREATEST(0, COALESCE(amount_to_payee, 0) - COALESCE(refunded_amount, 0)) AS net_amount,
      COALESCE(is_escrowed, FALSE) AS is_escrowed,
      escrow_released_at
    FROM "Payment"
    WHERE payee_id = p_user_id
      AND (p_start_date IS NULL OR created_at >= p_start_date)
      AND (p_end_date IS NULL OR created_at <= p_end_date)
      AND payment_status IN (
        'captured_hold', 'transfer_scheduled', 'transfer_pending', 'transferred',
        'refund_pending', 'refunded_partial', 'refunded_full', 'disputed',
        'succeeded', 'processing'
      )
  ),
  earnings AS (
    SELECT
      COUNT(*) AS total_payments,
      COALESCE(SUM(net_amount), 0) AS total_earned,
      COALESCE(SUM(CASE WHEN payment_status IN ('transferred', 'succeeded') THEN net_amount ELSE 0 END), 0) AS total_paid,
      COALESCE(SUM(CASE WHEN is_escrowed = TRUE AND escrow_released_at IS NULL THEN net_amount ELSE 0 END), 0) AS total_escrowed,
      COALESCE(SUM(CASE WHEN ((is_escrowed = FALSE) OR escrow_released_at IS NOT NULL OR payment_status IN ('transferred', 'succeeded')) THEN net_amount ELSE 0 END), 0) AS total_available
    FROM scoped
  )
  SELECT jsonb_build_object(
    'totalPayments', total_payments,
    'totalEarned', total_earned,
    'totalPaid', total_paid,
    'totalEscrowed', total_escrowed,
    'totalAvailable', total_available,
    'currency', 'USD'
  ) INTO v_result
  FROM earnings;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_user_earnings(p_user_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

--
-- Name: get_user_home_locations(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_home_locations(p_user_id uuid) RETURNS TABLE(home_id uuid, home_name text, address character varying, city character varying, state character varying, zipcode character varying, latitude double precision, longitude double precision)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    h.id        AS home_id,
    h.name      AS home_name,
    h.address,
    h.city,
    h.state,
    h.zipcode,
    COALESCE(
      CASE WHEN h.location IS NOT NULL THEN ST_Y(h.location::geometry) END,
      h.map_center_lat
    ) AS latitude,
    COALESCE(
      CASE WHEN h.location IS NOT NULL THEN ST_X(h.location::geometry) END,
      h.map_center_lng
    ) AS longitude
  FROM "HomeOccupancy" ho
  JOIN "Home" h ON ho.home_id = h.id
  WHERE ho.user_id = p_user_id
    AND ho.is_active = TRUE
  ORDER BY ho.created_at ASC;  -- first home = primary
END;
$$;


