--
-- Name: get_user_inbox(uuid, character varying, boolean, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_inbox(p_user_id uuid, p_type character varying DEFAULT NULL::character varying, p_viewed boolean DEFAULT NULL::boolean, p_archived boolean DEFAULT false, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id uuid, type character varying, subject character varying, sender_business_name character varying, viewed boolean, starred boolean, payout_amount numeric, created_at timestamp with time zone, expires_at timestamp with time zone)
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    m.id,
    m.type,
    m.subject,
    m.sender_business_name,
    m.viewed,
    m.starred,
    m.payout_amount,
    m.created_at,
    m.expires_at
  FROM "Mail" m
  WHERE 
    m.recipient_user_id = p_user_id
    AND m.archived = p_archived
    AND (p_type IS NULL OR m.type = p_type)
    AND (p_viewed IS NULL OR m.viewed = p_viewed)
    AND (m.expires_at IS NULL OR m.expires_at > NOW())
  ORDER BY m.created_at DESC
  LIMIT p_limit
  OFFSET p_offset;
END;
$$;


