--
-- Name: get_user_profile_with_media(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_profile_with_media(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'user', row_to_json(u.*),
    'skills', (
      SELECT jsonb_agg(row_to_json(s.*) ORDER BY s.display_order, s.skill_name)
      FROM "UserSkill" s
      WHERE s.user_id = p_user_id AND s.show_on_profile = TRUE
    ),
    'portfolio', (
      SELECT jsonb_agg(row_to_json(p.*) ORDER BY p.is_featured DESC, p.display_order, p.created_at DESC)
      FROM "UserPortfolio" p
      WHERE p.user_id = p_user_id AND p.is_visible = TRUE
    ),
    'certifications', (
      SELECT jsonb_agg(row_to_json(c.*) ORDER BY c.issue_date DESC)
      FROM "UserCertification" c
      WHERE c.user_id = p_user_id AND c.show_on_profile = TRUE
    ),
    'experience', (
      SELECT jsonb_agg(row_to_json(e.*) ORDER BY e.is_current DESC, e.start_date DESC)
      FROM "UserExperience" e
      WHERE e.user_id = p_user_id AND e.show_on_profile = TRUE
    )
  ) INTO v_result
  FROM "User" u
  WHERE u.id = p_user_id;
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_user_profile_with_media(p_user_id uuid) OWNER TO postgres;

--
-- Name: get_user_spending(uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_spending(p_user_id uuid, p_start_date timestamp with time zone DEFAULT NULL::timestamp with time zone, p_end_date timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  WITH scoped AS (
    SELECT
      amount_total,
      refunded_amount,
      payment_status
    FROM "Payment"
    WHERE payer_id = p_user_id
      AND (p_start_date IS NULL OR created_at >= p_start_date)
      AND (p_end_date IS NULL OR created_at <= p_end_date)
      AND payment_status IN (
        'captured_hold', 'transfer_scheduled', 'transfer_pending', 'transferred',
        'refund_pending', 'refunded_partial', 'refunded_full', 'disputed',
        'succeeded', 'processing'
      )
  ),
  spending AS (
    SELECT
      COUNT(*) AS total_payments,
      COALESCE(SUM(amount_total), 0) AS total_spent,
      COALESCE(SUM(GREATEST(0, amount_total - COALESCE(refunded_amount, 0))), 0) AS total_paid,
      COALESCE(SUM(COALESCE(refunded_amount, 0)), 0) AS total_refunded
    FROM scoped
  )
  SELECT jsonb_build_object(
    'totalPayments', total_payments,
    'totalSpent', total_spent,
    'totalPaid', total_paid,
    'totalRefunded', total_refunded,
    'currency', 'USD'
  ) INTO v_result
  FROM spending;

  RETURN v_result;
END;
$$;


ALTER FUNCTION public.get_user_spending(p_user_id uuid, p_start_date timestamp with time zone, p_end_date timestamp with time zone) OWNER TO postgres;

--
-- Name: get_user_storage_stats(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_user_storage_stats(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_stats JSONB;
BEGIN
  WITH grouped AS (
    SELECT file_type, count(*) AS file_count, sum(file_size) AS total_size
    FROM public."File" WHERE user_id = p_user_id AND is_deleted = FALSE
    GROUP BY file_type
  )
  SELECT CASE WHEN count(*) = 0 THEN '{}'::jsonb ELSE jsonb_build_object(
    'totalFiles', sum(file_count), 'totalSize', sum(total_size),
    'byType', jsonb_object_agg(file_type, jsonb_build_object('count', file_count, 'size', total_size))
  ) END INTO v_stats FROM grouped;

  RETURN COALESCE(v_stats, '{}'::jsonb);
END;
$$;


