-- Name: identity_search_visibility_rank(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.identity_search_visibility_rank(visibility text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE visibility
    WHEN 'nobody' THEN 0
    WHEN 'mutuals' THEN 1
    WHEN 'everyone' THEN 2
    ELSE 2
  END;
$$;


