--
-- Name: public_persona_audience_handle_validate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.public_persona_audience_handle_validate() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM "public"."AudienceIdentity" ai
    WHERE ai."handle_normalized" = NEW."handle_normalized"
      AND ai."user_id" <> NEW."user_id"
  ) THEN
    RAISE EXCEPTION 'Beacon handle conflicts with an audience identity handle';
  END IF;

  RETURN NEW;
END;
$$;


