--
-- Name: record_post_unique_view(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_post_unique_view(p_post_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_row_count integer := 0;
BEGIN
  IF p_post_id IS NULL OR p_user_id IS NULL THEN
    RETURN false;
  END IF;

  INSERT INTO "PostView" ("post_id", "user_id")
  VALUES (p_post_id, p_user_id)
  ON CONFLICT ("post_id", "user_id") DO NOTHING;

  GET DIAGNOSTICS v_row_count = ROW_COUNT;

  IF v_row_count > 0 THEN
    UPDATE "Post"
    SET "view_count" = COALESCE("view_count", 0) + 1
    WHERE "id" = p_post_id;
    RETURN true;
  END IF;

  RETURN false;
END;
$$;


ALTER FUNCTION public.record_post_unique_view(p_post_id uuid, p_user_id uuid) OWNER TO postgres;

