--
-- Name: release_job_lock(text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.release_job_lock(p_job_name text, p_locked_by text, p_success boolean, p_error text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE public.job_locks
  SET expires_at = now(),  -- immediately expire
      last_success = CASE WHEN p_success THEN now() ELSE last_success END,
      last_failure = CASE WHEN NOT p_success THEN now() ELSE last_failure END,
      last_error = CASE WHEN NOT p_success THEN p_error ELSE last_error END
  WHERE job_name = p_job_name AND locked_by = p_locked_by;
END;
$$;


ALTER FUNCTION public.release_job_lock(p_job_name text, p_locked_by text, p_success boolean, p_error text) OWNER TO postgres;

--
-- Name: resource_predelete_cleanup(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.resource_predelete_cleanup() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM "public"."Booking" WHERE "resource_id" = OLD."id" AND "event_type_id" IS NULL;
  RETURN OLD;
END;
