--
-- Name: soft_delete_file(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.soft_delete_file(p_file_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_file RECORD;
BEGIN
  -- Get file
  SELECT * INTO v_file
  FROM "File"
  WHERE id = p_file_id AND user_id = p_user_id AND is_deleted = FALSE;
  
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'File not found or already deleted');
  END IF;
  
  -- Mark as deleted
  UPDATE "File"
  SET 
    is_deleted = TRUE,
    deleted_at = NOW(),
    updated_at = NOW()
  WHERE id = p_file_id;
  
  -- Update quota
  UPDATE "FileQuota"
  SET 
    storage_used = GREATEST(storage_used - v_file.file_size, 0),
    file_count = GREATEST(file_count - 1, 0),
    updated_at = NOW()
  WHERE user_id = p_user_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'fileId', p_file_id,
    'freedSpace', v_file.file_size
  );
END;
$$;


ALTER FUNCTION public.soft_delete_file(p_file_id uuid, p_user_id uuid) OWNER TO postgres;

