--
-- Name: toggle_comment_like(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_comment_like(p_comment_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exists BOOLEAN;
  v_new_count INT;
BEGIN
  SELECT EXISTS(
    SELECT 1 FROM "CommentLike"
    WHERE comment_id = p_comment_id AND user_id = p_user_id
  ) INTO v_exists;

  IF v_exists THEN
    DELETE FROM "CommentLike"
    WHERE comment_id = p_comment_id AND user_id = p_user_id;

    UPDATE "PostComment"
    SET like_count = GREATEST(like_count - 1, 0)
    WHERE id = p_comment_id
    RETURNING like_count INTO v_new_count;

    RETURN jsonb_build_object(
      'liked', false,
      'likeCount', COALESCE(v_new_count, 0)
    );
  ELSE
    INSERT INTO "CommentLike" (comment_id, user_id)
    VALUES (p_comment_id, p_user_id);

    UPDATE "PostComment"
    SET like_count = like_count + 1
    WHERE id = p_comment_id
    RETURNING like_count INTO v_new_count;

    RETURN jsonb_build_object(
      'liked', true,
      'likeCount', v_new_count
    );
  END IF;
END;
$$;


ALTER FUNCTION public.toggle_comment_like(p_comment_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: toggle_listing_save(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_listing_save(p_listing_id uuid, p_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_exists boolean;
BEGIN
    SELECT EXISTS(
        SELECT 1 FROM "ListingSave"
        WHERE listing_id = p_listing_id AND user_id = p_user_id
    ) INTO v_exists;

    IF v_exists THEN
        DELETE FROM "ListingSave"
        WHERE listing_id = p_listing_id AND user_id = p_user_id;

        UPDATE "Listing" SET save_count = GREATEST(save_count - 1, 0)
        WHERE id = p_listing_id;

        RETURN false; -- unsaved
    ELSE
        INSERT INTO "ListingSave" (listing_id, user_id) VALUES (p_listing_id, p_user_id);

        UPDATE "Listing" SET save_count = save_count + 1
        WHERE id = p_listing_id;

        RETURN true; -- saved
    END IF;
END;
$$;


ALTER FUNCTION public.toggle_listing_save(p_listing_id uuid, p_user_id uuid) OWNER TO postgres;

--
-- Name: toggle_post_like(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.toggle_post_like(p_post_id uuid, p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_exists BOOLEAN;
  v_new_count INT;
BEGIN
  -- Check if like exists
  SELECT EXISTS(
    SELECT 1 FROM "PostLike" 
    WHERE post_id = p_post_id AND user_id = p_user_id
  ) INTO v_exists;
  
  IF v_exists THEN
    -- Unlike
    DELETE FROM "PostLike" 
    WHERE post_id = p_post_id AND user_id = p_user_id;
    
    UPDATE "Post" 
    SET like_count = GREATEST(like_count - 1, 0)
    WHERE id = p_post_id
    RETURNING like_count INTO v_new_count;
    
    RETURN jsonb_build_object(
      'liked', false,
      'likeCount', v_new_count
    );
  ELSE
    -- Like
    INSERT INTO "PostLike" (post_id, user_id)
    VALUES (p_post_id, p_user_id);
    
    UPDATE "Post" 
    SET like_count = like_count + 1
    WHERE id = p_post_id
    RETURNING like_count INTO v_new_count;
    
    RETURN jsonb_build_object(
      'liked', true,
      'likeCount', v_new_count
    );
  END IF;
END;
$$;


ALTER FUNCTION public.toggle_post_like(p_post_id uuid, p_user_id uuid) OWNER TO postgres;

