-- Name: WalletTransaction; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public."WalletTransaction" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    wallet_id uuid NOT NULL,
    user_id uuid NOT NULL,
    type character varying(30) NOT NULL,
    amount bigint NOT NULL,
    direction character varying(6) NOT NULL,
    balance_before bigint NOT NULL,
    balance_after bigint NOT NULL,
    description text,
    currency character varying(3) DEFAULT 'usd'::character varying NOT NULL,
    payment_id uuid,
    gig_id uuid,
    counterparty_id uuid,
    stripe_payment_intent_id character varying(255),
    stripe_transfer_id character varying(255),
    idempotency_key character varying(255),
    status character varying(20) DEFAULT 'completed'::character varying NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamp with time zone DEFAULT now(),
    CONSTRAINT "WalletTransaction_amount_pos" CHECK ((amount > 0)),
    CONSTRAINT "WalletTransaction_direction_check" CHECK (((direction)::text = ANY (ARRAY[('credit'::character varying)::text, ('debit'::character varying)::text]))),
    CONSTRAINT "WalletTransaction_status_check" CHECK (((status)::text = ANY (ARRAY[('completed'::character varying)::text, ('pending'::character varying)::text, ('failed'::character varying)::text, ('reversed'::character varying)::text]))),
    CONSTRAINT "WalletTransaction_type_check" CHECK (((type)::text = ANY (ARRAY[('deposit'::character varying)::text, ('withdrawal'::character varying)::text, ('gig_income'::character varying)::text, ('gig_payment'::character varying)::text, ('tip_income'::character varying)::text, ('tip_sent'::character varying)::text, ('refund'::character varying)::text, ('adjustment'::character varying)::text, ('transfer_in'::character varying)::text, ('transfer_out'::character varying)::text, ('cancellation_fee'::character varying)::text, ('withdrawal_reversal'::character varying)::text, ('booking_income'::character varying)::text, ('package_income'::character varying)::text])))
);


ALTER TABLE public."WalletTransaction" OWNER TO postgres;

--
-- Name: wallet_credit(uuid, bigint, character varying, text, uuid, uuid, uuid, character varying, character varying, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.wallet_credit(p_user_id uuid, p_amount bigint, p_type character varying, p_description text DEFAULT NULL::text, p_payment_id uuid DEFAULT NULL::uuid, p_gig_id uuid DEFAULT NULL::uuid, p_counterparty_id uuid DEFAULT NULL::uuid, p_stripe_pi_id character varying DEFAULT NULL::character varying, p_idempotency_key character varying DEFAULT NULL::character varying, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public."WalletTransaction"
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_wallet "public"."Wallet";
  v_tx     "public"."WalletTransaction";
  v_balance_before bigint;
  v_balance_after  bigint;
BEGIN
  SELECT * INTO v_wallet FROM get_or_create_wallet(p_user_id);

  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx FROM "WalletTransaction"
    WHERE idempotency_key = p_idempotency_key;
    IF v_tx IS NOT NULL THEN
      RETURN v_tx;
    END IF;
  END IF;

  SELECT * INTO v_wallet FROM "Wallet"
  WHERE id = v_wallet.id
  FOR UPDATE;

  IF v_wallet.frozen THEN
    RAISE EXCEPTION 'Wallet is frozen';
  END IF;

  v_balance_before := v_wallet.balance;
  v_balance_after  := v_wallet.balance + p_amount;

  UPDATE "Wallet"
  SET balance = v_balance_after,
      lifetime_received = CASE
        WHEN p_type IN ('gig_income', 'tip_income', 'booking_income', 'package_income') THEN lifetime_received + p_amount
        ELSE lifetime_received
      END,
      lifetime_deposits = CASE
        WHEN p_type = 'deposit' THEN lifetime_deposits + p_amount
        ELSE lifetime_deposits
      END,
      lifetime_withdrawals = CASE
        WHEN p_type = 'withdrawal_reversal' THEN GREATEST(lifetime_withdrawals - p_amount, 0)
        ELSE lifetime_withdrawals
      END,
      updated_at = now()
  WHERE id = v_wallet.id;

  INSERT INTO "WalletTransaction" (
    wallet_id, user_id, type, amount, direction,
    balance_before, balance_after, description,
    payment_id, gig_id, counterparty_id,
    stripe_payment_intent_id, idempotency_key, metadata
  ) VALUES (
    v_wallet.id, p_user_id, p_type, p_amount, 'credit',
    v_balance_before, v_balance_after, p_description,
    p_payment_id, p_gig_id, p_counterparty_id,
    p_stripe_pi_id, p_idempotency_key, p_metadata
  )
  RETURNING * INTO v_tx;

  RETURN v_tx;
END;
$$;


ALTER FUNCTION public.wallet_credit(p_user_id uuid, p_amount bigint, p_type character varying, p_description text, p_payment_id uuid, p_gig_id uuid, p_counterparty_id uuid, p_stripe_pi_id character varying, p_idempotency_key character varying, p_metadata jsonb) OWNER TO postgres;

--
-- Name: wallet_debit(uuid, bigint, character varying, text, uuid, uuid, uuid, character varying, character varying, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.wallet_debit(p_user_id uuid, p_amount bigint, p_type character varying, p_description text DEFAULT NULL::text, p_payment_id uuid DEFAULT NULL::uuid, p_gig_id uuid DEFAULT NULL::uuid, p_counterparty_id uuid DEFAULT NULL::uuid, p_stripe_transfer character varying DEFAULT NULL::character varying, p_idempotency_key character varying DEFAULT NULL::character varying, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS public."WalletTransaction"
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_wallet "public"."Wallet";
  v_tx     "public"."WalletTransaction";
  v_balance_before bigint;
  v_balance_after  bigint;
BEGIN
  -- Ensure wallet exists
  SELECT * INTO v_wallet FROM get_or_create_wallet(p_user_id);

  -- Check idempotency
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO v_tx FROM "WalletTransaction"
    WHERE idempotency_key = p_idempotency_key;
    IF v_tx IS NOT NULL THEN
      RETURN v_tx;  -- Already processed
    END IF;
  END IF;

  -- Lock the wallet row for update
  SELECT * INTO v_wallet FROM "Wallet"
  WHERE id = v_wallet.id
  FOR UPDATE;

  IF v_wallet.frozen THEN
    RAISE EXCEPTION 'Wallet is frozen';
  END IF;

  v_balance_before := v_wallet.balance;
  v_balance_after  := v_wallet.balance - p_amount;

  -- Check sufficient balance
  IF v_balance_after < 0 THEN
    RAISE EXCEPTION 'Insufficient wallet balance. Available: %, Required: %',
      v_wallet.balance, p_amount;
  END IF;

  -- Update balance
  UPDATE "Wallet"
  SET balance = v_balance_after,
      lifetime_spent = CASE
        WHEN p_type IN ('gig_payment', 'tip_sent') THEN lifetime_spent + p_amount
        ELSE lifetime_spent
      END,
      lifetime_withdrawals = CASE
        WHEN p_type = 'withdrawal' THEN lifetime_withdrawals + p_amount
        ELSE lifetime_withdrawals
      END,
      updated_at = now()
  WHERE id = v_wallet.id;

  -- Insert ledger entry
  INSERT INTO "WalletTransaction" (
    wallet_id, user_id, type, amount, direction,
    balance_before, balance_after, description,
    payment_id, gig_id, counterparty_id,
    stripe_transfer_id, idempotency_key, metadata
  ) VALUES (
    v_wallet.id, p_user_id, p_type, p_amount, 'debit',
    v_balance_before, v_balance_after, p_description,
    p_payment_id, p_gig_id, p_counterparty_id,
    p_stripe_transfer, p_idempotency_key, p_metadata
  )
  RETURNING * INTO v_tx;

  RETURN v_tx;
END;
$$;


ALTER FUNCTION public.wallet_debit(p_user_id uuid, p_amount bigint, p_type character varying, p_description text, p_payment_id uuid, p_gig_id uuid, p_counterparty_id uuid, p_stripe_transfer character varying, p_idempotency_key character varying, p_metadata jsonb) OWNER TO postgres;

--
-- Name: wallet_transfer(uuid, uuid, bigint, character varying, character varying, text, uuid, uuid, character varying, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.wallet_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount bigint, p_type_debit character varying, p_type_credit character varying, p_description text DEFAULT NULL::text, p_payment_id uuid DEFAULT NULL::uuid, p_gig_id uuid DEFAULT NULL::uuid, p_idempotency_key character varying DEFAULT NULL::character varying, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS TABLE(debit_tx uuid, credit_tx uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_debit_tx  "public"."WalletTransaction";
  v_credit_tx "public"."WalletTransaction";
  v_debit_key varchar(255);
  v_credit_key varchar(255);
BEGIN
  -- Create paired idempotency keys
  v_debit_key  := CASE WHEN p_idempotency_key IS NOT NULL
                       THEN p_idempotency_key || ':debit' ELSE NULL END;
  v_credit_key := CASE WHEN p_idempotency_key IS NOT NULL
                       THEN p_idempotency_key || ':credit' ELSE NULL END;

  -- Debit the payer
  SELECT * INTO v_debit_tx FROM wallet_debit(
    p_from_user_id, p_amount, p_type_debit, p_description,
    p_payment_id, p_gig_id, p_to_user_id, NULL, v_debit_key, p_metadata
  );

  -- Credit the payee
  SELECT * INTO v_credit_tx FROM wallet_credit(
    p_to_user_id, p_amount, p_type_credit, p_description,
    p_payment_id, p_gig_id, p_from_user_id, NULL, v_credit_key, p_metadata
  );

  RETURN QUERY SELECT v_debit_tx.id, v_credit_tx.id;
END;
$$;


ALTER FUNCTION public.wallet_transfer(p_from_user_id uuid, p_to_user_id uuid, p_amount bigint, p_type_debit character varying, p_type_credit character varying, p_description text, p_payment_id uuid, p_gig_id uuid, p_idempotency_key character varying, p_metadata jsonb) OWNER TO postgres;

