    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT "EventType_default_duration_chk" CHECK ((default_duration > 0)),
    CONSTRAINT "EventType_owner_chk" CHECK ((((owner_type = 'home'::public.scheduling_owner_type) AND (home_id IS NOT NULL) AND (owner_user_id IS NULL) AND (owner_id = home_id)) OR ((owner_type = ANY (ARRAY['user'::public.scheduling_owner_type, 'business'::public.scheduling_owner_type])) AND (owner_user_id IS NOT NULL) AND (home_id IS NULL) AND (owner_id = owner_user_id)))),
    CONSTRAINT "EventType_seat_cap_chk" CHECK ((seat_cap >= 1)),
    CONSTRAINT "EventType_slot_interval_chk" CHECK ((slot_interval_min > 0)),
    CONSTRAINT "EventType_visibility_chk" CHECK ((visibility = ANY (ARRAY['public'::text, 'secret'::text])))
);


