-- Name: Gig; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public."Gig" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    title character varying(255) NOT NULL,
    description text NOT NULL,
    price numeric(10,2) NOT NULL,
    category character varying(100),
    deadline timestamp with time zone,
    estimated_duration double precision,
    attachments text[] DEFAULT '{}'::text[],
    exact_location public.geography(Point,4326),
    approx_location public.geography(Point,4326),
    user_id uuid NOT NULL,
    status character varying(50) DEFAULT 'open'::character varying,
    accepted_by uuid,
    accepted_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    estimated_dur numeric,
    created_by uuid,
    beneficiary_user_id uuid,
    origin_home_id uuid,
    origin_user_place_id uuid,
    exact_address text,
    exact_city text,
    exact_state text,
    exact_zip text,
    origin_mode text,
    origin_place_id text,
    started_at timestamp with time zone,
    worker_completed_at timestamp with time zone,
    owner_confirmed_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    cancellation_reason text,
    cancellation_policy text DEFAULT 'standard'::text,
    cancelled_by uuid,
    cancellation_zone smallint,
    cancellation_fee numeric(10,2) DEFAULT 0,
    scheduled_start timestamp with time zone,
    completion_note text,
    completion_photos text[] DEFAULT '{}'::text[],
    completion_checklist jsonb DEFAULT '[]'::jsonb,
    owner_confirmation_note text,
    owner_satisfaction smallint,
    payment_id uuid,
    payment_status character varying(50) DEFAULT 'none'::character varying,
    location_precision public.location_precision DEFAULT 'approx_area'::public.location_precision,
    reveal_policy public.reveal_policy DEFAULT 'after_assignment'::public.reveal_policy,
    visibility_scope public.visibility_scope DEFAULT 'city'::public.visibility_scope,
    radius_miles numeric(8,2) DEFAULT 100,
    is_urgent boolean DEFAULT false,
    tags text[] DEFAULT '{}'::text[],
    ref_listing_id uuid,
    items jsonb DEFAULT '[]'::jsonb,
    source_type text,
    source_id uuid,
    ref_post_id uuid,
    schedule_type public.schedule_type DEFAULT 'asap'::public.schedule_type,
    pay_type public.pay_type DEFAULT 'fixed'::public.pay_type,
    time_window_start timestamp with time zone,
    time_window_end timestamp with time zone,
    language_preference text,
    access_notes text,
    required_tools text[],
    special_instructions text,
    preferred_helper_id uuid,
    source_flow public.task_source_flow,
    ai_confidence numeric(3,2),
    ai_draft_json jsonb,
    undo_expires_at timestamp with time zone,
    helper_eta_minutes integer,
    helper_last_location public.geography(Point,4326),
    helper_location_updated_at timestamp with time zone,
    status_share_token text,
    status_share_expires_at timestamp with time zone,
    requires_license boolean DEFAULT false,
    license_type text,
    requires_insurance boolean DEFAULT false,
    deposit_required boolean DEFAULT false,
    deposit_amount numeric(10,2),
    scope_description text,
    pickup_address text,
    pickup_location public.geography(Point,4326),
    pickup_notes text,
    dropoff_address text,
    dropoff_location public.geography(Point,4326),
    dropoff_notes text,
    delivery_proof_required boolean DEFAULT false,
    delivery_proof_photos text[],
    delivery_proof_qr text,
    engagement_mode public.engagement_mode DEFAULT 'curated_offers'::public.engagement_mode,
    geocode_provider text,
    geocode_mode text,
    geocode_accuracy text,
    geocode_place_id text,
    geocode_created_at timestamp with time zone DEFAULT now(),
    geocode_source_flow text,
    task_archetype public.task_archetype DEFAULT 'general'::public.task_archetype,
    care_details jsonb,
    logistics_details jsonb,
    remote_details jsonb,
    urgent_details jsonb,
    event_details jsonb,
    starts_asap boolean DEFAULT false,
    response_window_minutes integer,
    last_worker_reminder_at timestamp with time zone,
    worker_ack_status character varying(50),
    worker_ack_eta_minutes integer,
    worker_ack_note text,
    worker_ack_updated_at timestamp with time zone,
    auto_reminder_count integer DEFAULT 0,
    allow_external_share boolean DEFAULT true NOT NULL,
    cap_amount_cents integer,
    cap_period public.cap_period,
    estimated_units numeric,
    is_negotiable boolean DEFAULT false,
    pay_unit public.pay_unit,
    pricing_mode public.pricing_mode,
    pricing_notes text,
    rate_amount_cents integer,
    rate_max_amount_cents integer,
    recurrence jsonb,
    schedule_end_at timestamp with time zone,
    schedule_pattern public.schedule_pattern,
    schedule_start_at timestamp with time zone,
    service_type text,
    share_count integer DEFAULT 0 NOT NULL,
    unit_label text,
    CONSTRAINT "Gig_price_check" CHECK (((price IS NULL) OR (price >= (0)::numeric))),
    CONSTRAINT "Gig_status_check" CHECK (((status)::text = ANY (ARRAY['open'::text, 'assigned'::text, 'in_progress'::text, 'completed'::text, 'cancelled'::text, 'draft'::text]))),
    CONSTRAINT gig_cap_amount_period_together CHECK (((cap_amount_cents IS NULL) = (cap_period IS NULL))),
    CONSTRAINT gig_origin_mode_check CHECK ((origin_mode = ANY (ARRAY['home'::text, 'address'::text, 'current'::text]))),
    CONSTRAINT gig_pay_unit_item_requires_label CHECK (((pay_unit IS DISTINCT FROM 'item'::public.pay_unit) OR (unit_label IS NOT NULL))),
    CONSTRAINT gig_pricing_mode_range_requires_fields CHECK (((pricing_mode <> 'range'::public.pricing_mode) OR ((rate_amount_cents IS NOT NULL) AND (rate_max_amount_cents IS NOT NULL) AND (rate_max_amount_cents >= rate_amount_cents)))),
    CONSTRAINT gig_pricing_mode_rate_requires_fields CHECK (((pricing_mode <> 'rate'::public.pricing_mode) OR ((rate_amount_cents IS NOT NULL) AND (pay_unit IS NOT NULL)))),
    CONSTRAINT gig_pricing_mode_unpriced_has_no_amount CHECK (((pricing_mode <> ALL (ARRAY['quote_only'::public.pricing_mode, 'free'::public.pricing_mode, 'barter'::public.pricing_mode])) OR ((rate_amount_cents IS NULL) AND (cap_amount_cents IS NULL)))),
    CONSTRAINT gig_schedule_pattern_requires_recurrence CHECK (((schedule_pattern IS NULL) OR (schedule_pattern <> ALL (ARRAY['recurring'::public.schedule_pattern, 'multi_day_span'::public.schedule_pattern])) OR (recurrence IS NOT NULL))),
    CONSTRAINT gig_source_type_check CHECK (((source_type IS NULL) OR (source_type = ANY (ARRAY['listing'::text, 'post'::text, 'event'::text]))))
);


ALTER TABLE public."Gig" OWNER TO postgres;

