--

COMMENT ON COLUMN public."Gig".worker_ack_note IS 'Free-text note from the worker';


--
-- Name: COLUMN "Gig".worker_ack_updated_at; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public."Gig".worker_ack_updated_at IS 'When the worker last updated their acknowledgement';


--
-- Name: COLUMN "Gig".auto_reminder_count; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public."Gig".auto_reminder_count IS 'Number of automatic start-work reminders sent to the assigned worker (capped at 2)';


