    CONSTRAINT "HomeAccessSecret_type_chk" CHECK ((access_type = ANY (ARRAY['wifi'::text, 'door_code'::text, 'gate_code'::text, 'lockbox'::text, 'garage'::text, 'alarm'::text, 'other'::text])))
);


