-- Name: Listing; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public."Listing" (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    user_id uuid NOT NULL,
    title text NOT NULL,
    description text,
    price numeric(10,2),
    is_free boolean DEFAULT false,
    category public.listing_category DEFAULT 'other'::public.listing_category NOT NULL,
    subcategory text,
    condition public.listing_condition,
    quantity integer DEFAULT 1,
    status public.listing_status DEFAULT 'active'::public.listing_status,
    media_urls text[] DEFAULT '{}'::text[],
    media_types text[] DEFAULT '{}'::text[],
    latitude double precision,
    longitude double precision,
    location public.geography(Point,4326),
    location_name text,
    location_address text,
    location_precision public.location_precision DEFAULT 'approx_area'::public.location_precision,
    reveal_policy public.reveal_policy DEFAULT 'after_interest'::public.reveal_policy,
    visibility_scope public.visibility_scope DEFAULT 'city'::public.visibility_scope,
    radius_miles numeric(8,2) DEFAULT 100,
    meetup_preference text DEFAULT 'public_meetup'::text,
    delivery_available boolean DEFAULT false,
    available_from timestamp with time zone,
    available_until timestamp with time zone,
    tags text[] DEFAULT '{}'::text[],
    view_count integer DEFAULT 0,
    save_count integer DEFAULT 0,
    message_count integer DEFAULT 0,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    sold_at timestamp with time zone,
    archived_at timestamp with time zone,
    search_vector tsvector GENERATED ALWAYS AS ((setweight(to_tsvector('english'::regconfig, COALESCE(title, ''::text)), 'A'::"char") || setweight(to_tsvector('english'::regconfig, COALESCE(description, ''::text)), 'B'::"char"))) STORED,
    source_type text,
    source_id uuid,
    layer public.listing_layer DEFAULT 'goods'::public.listing_layer,
    listing_type public.listing_type DEFAULT 'sell_item'::public.listing_type,
    home_id uuid,
    is_address_attached boolean DEFAULT false,
    expires_at timestamp with time zone,
    last_refreshed_at timestamp with time zone,
    refresh_count integer DEFAULT 0,
    quality_score numeric(4,2) DEFAULT 0.00,
    risk_score numeric(4,2) DEFAULT 0.00,
    context_tags text[] DEFAULT '{}'::text[],
    is_wanted boolean DEFAULT false,
    budget_max numeric(10,2),
    geocode_provider text,
    geocode_mode text,
    geocode_accuracy text,
    geocode_place_id text,
    geocode_created_at timestamp with time zone DEFAULT now(),
    geocode_source_flow text,
    open_to_trades boolean DEFAULT false,
    trade_preferences text,
    ingredients text[],
    allergens text[],
    preparation_date date,
    best_by_date date,
    food_handler_certified boolean DEFAULT false,
    is_recurring boolean DEFAULT false,
    recurrence_schedule jsonb,
    is_preorder boolean DEFAULT false,
    preorder_deadline timestamp with time zone,
    preorder_fulfillment_date date,
    active_offer_count integer DEFAULT 0,
    media_thumbnails text[],
    allow_external_share boolean DEFAULT true NOT NULL,
    share_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT "Listing_budget_max_check" CHECK (((budget_max IS NULL) OR (budget_max >= (0)::numeric))),
    CONSTRAINT "Listing_price_check" CHECK (((price >= (0)::numeric) OR (price IS NULL))),
    CONSTRAINT "Listing_quality_score_check" CHECK (((quality_score >= (0)::numeric) AND (quality_score <= (10)::numeric))),
    CONSTRAINT "Listing_risk_score_check" CHECK (((risk_score >= (0)::numeric) AND (risk_score <= (10)::numeric))),
    CONSTRAINT listing_layer_type_check CHECK ((((layer = 'goods'::public.listing_layer) AND (listing_type = ANY (ARRAY['sell_item'::public.listing_type, 'free_item'::public.listing_type, 'wanted_request'::public.listing_type]))) OR ((layer = 'gigs'::public.listing_layer) AND (listing_type = 'service_gig'::public.listing_type)) OR ((layer = 'rentals'::public.listing_layer) AND (listing_type = 'rent_sublet'::public.listing_type)) OR ((layer = 'vehicles'::public.listing_layer) AND (listing_type = ANY (ARRAY['vehicle_sale'::public.listing_type, 'vehicle_rent'::public.listing_type]))))),
    CONSTRAINT listing_source_type_check CHECK (((source_type IS NULL) OR (source_type = ANY (ARRAY['gig'::text, 'post'::text]))))
);


ALTER TABLE public."Listing" OWNER TO postgres;

