    CONSTRAINT "Post_post_type_check" CHECK (((post_type)::text = ANY (ARRAY[('ask_local'::character varying)::text, ('recommendation'::character varying)::text, ('event'::character varying)::text, ('lost_found'::character varying)::text, ('alert'::character varying)::text, ('deal'::character varying)::text, ('local_update'::character varying)::text, ('neighborhood_win'::character varying)::text, ('visitor_guide'::character varying)::text, ('general'::character varying)::text, ('personal_update'::character varying)::text, ('announcement'::character varying)::text, ('service_offer'::character varying)::text, ('resources_howto'::character varying)::text, ('progress_wins'::character varying)::text]))),
    CONSTRAINT "Post_profile_visibility_scope_check" CHECK (((profile_visibility_scope)::text = ANY (ARRAY[('public'::character varying)::text, ('followers'::character varying)::text, ('connections'::character varying)::text, ('local_context'::character varying)::text, ('hidden'::character varying)::text]))),
    CONSTRAINT "Post_purpose_check" CHECK (((purpose IS NULL) OR ((purpose)::text = ANY (ARRAY[('ask'::character varying)::text, ('offer'::character varying)::text, ('heads_up'::character varying)::text, ('recommend'::character varying)::text, ('lost_found'::character varying)::text, ('local_update'::character varying)::text, ('neighborhood_win'::character varying)::text, ('visitor_guide'::character varying)::text, ('learn'::character varying)::text, ('showcase'::character varying)::text, ('story'::character varying)::text, ('event'::character varying)::text, ('deal'::character varying)::text])))),
    CONSTRAINT "Post_sports_scope_check" CHECK (((sports_scope IS NULL) OR (sports_scope = ANY (ARRAY['local'::text, 'regional'::text, 'national'::text, 'youth'::text, 'school'::text, 'rec'::text, 'watch'::text])))),
    CONSTRAINT "Post_state_check" CHECK (((state)::text = ANY (ARRAY[('open'::character varying)::text, ('solved'::character varying)::text, ('archived'::character varying)::text]))),
    CONSTRAINT "Post_target_tier_rank_check" CHECK (((target_tier_rank IS NULL) OR ((target_tier_rank >= 1) AND (target_tier_rank <= 4)))),
    CONSTRAINT "Post_topic_check" CHECK (((topic IS NULL) OR (topic = 'sports'::text))),
    CONSTRAINT "Post_visibility_check" CHECK (((visibility)::text = ANY (ARRAY['public'::text, 'neighborhood'::text, 'followers'::text, 'private'::text, 'city'::text, 'radius'::text, 'connections'::text])))
);


