--
-- Name: PublicLocalProfileView; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public."PublicLocalProfileView" AS
 SELECT lp.id,
    lp.handle,
    lp.handle_normalized,
    lp.display_name,
    lp.avatar_url,
    lp.bio,
    lp.tagline,
        CASE
            WHEN (lp.show_neighborhood IS TRUE) THEN lp.public_city
            ELSE NULL::text
        END AS public_city,
        CASE
            WHEN (lp.show_neighborhood IS TRUE) THEN lp.public_state
            ELSE NULL::text
        END AS public_state,
        CASE
            WHEN (lp.show_neighborhood IS TRUE) THEN lp.public_neighborhood
            ELSE NULL::text
        END AS public_neighborhood,
    lp.show_verified_resident_badge,
    lp.show_home_affiliation,
    lp.show_neighborhood,
    lp.profile_visibility,
    lp.created_at,
    lp.updated_at
   FROM (public."LocalProfile" lp
     LEFT JOIN public."UserPrivacySettings" ups ON ((ups.user_id = lp.user_id)))
  WHERE ((lp.profile_visibility = 'public'::text) AND (lp.search_visibility = 'everyone'::text) AND (COALESCE((ups.search_visibility)::text, 'everyone'::text) = 'everyone'::text));


