    event_key text NOT NULL,
    display_name text NOT NULL,
    short_label text NOT NULL,
    league text NOT NULL,
    country text DEFAULT 'US'::text NOT NULL,
    starts_at timestamp with time zone NOT NULL,
    ends_at timestamp with time zone NOT NULL,
    priority integer DEFAULT 100 NOT NULL,
    cadence jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


ALTER TABLE public.sports_events OWNER TO postgres;

--
-- Name: active_sports_events; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.active_sports_events AS
 SELECT event_key,
    display_name,
    short_label,
    league,
    country,
    starts_at,
    ends_at,
    priority,
    cadence,
    created_at,
    updated_at
   FROM public.sports_events
  WHERE ((starts_at <= now()) AND (ends_at >= now()))
  ORDER BY priority, starts_at DESC;


ALTER VIEW public.active_sports_events OWNER TO postgres;

