--
-- Name: seeder_content_queue; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.seeder_content_queue (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    source text NOT NULL,
    source_url text,
    raw_title text NOT NULL,
    raw_body text,
    region text NOT NULL,
    category text NOT NULL,
    fetched_at timestamp with time zone DEFAULT now() NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    humanized_text text,
    post_id uuid,
    scheduled_for timestamp with time zone,
    dedup_hash text NOT NULL,
    parent_id uuid,
    failure_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    media_urls text[] DEFAULT '{}'::text[] NOT NULL,
    media_types text[] DEFAULT '{}'::text[] NOT NULL,
    source_priority smallint DEFAULT 2 NOT NULL,
    scope text DEFAULT 'local'::text NOT NULL,
    event_key text,
    CONSTRAINT seeder_content_queue_category_check CHECK ((category = ANY (ARRAY['local_news'::text, 'event'::text, 'weather'::text, 'seasonal'::text, 'community_resource'::text, 'safety'::text, 'air_quality'::text, 'earthquake'::text, 'history'::text, 'sports'::text]))),
    CONSTRAINT seeder_content_queue_scope_check CHECK ((scope = ANY (ARRAY['local'::text, 'national'::text]))),
    CONSTRAINT seeder_content_queue_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'filtered_out'::text, 'humanized'::text, 'posted'::text, 'skipped'::text, 'failed'::text])))
);


ALTER TABLE public.seeder_content_queue OWNER TO postgres;

--
-- Name: COLUMN seeder_content_queue.media_urls; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.seeder_content_queue.media_urls IS 'Image/video URLs extracted from source (RSS media:content, enclosures, etc.)';


--
-- Name: COLUMN seeder_content_queue.media_types; Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON COLUMN public.seeder_content_queue.media_types IS 'Parallel array of media types — image, video (matches Pantopus Post.media_types)';


