--
-- Name: MessageReaction Active participants can add reactions; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Active participants can add reactions" ON public."MessageReaction" FOR INSERT WITH CHECK (((auth.uid() = user_id) AND (message_id IN ( SELECT "ChatMessage".id
   FROM public."ChatMessage"
  WHERE ("ChatMessage".room_id IN ( SELECT "ChatParticipant".room_id
           FROM public."ChatParticipant"
          WHERE (("ChatParticipant".user_id = auth.uid()) AND ("ChatParticipant".is_active = true))))))));


--
-- Name: MessageReaction Active participants can view reactions; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "Active participants can view reactions" ON public."MessageReaction" FOR SELECT USING ((message_id IN ( SELECT "ChatMessage".id
   FROM public."ChatMessage"
  WHERE ("ChatMessage".room_id IN ( SELECT "ChatParticipant".room_id
           FROM public."ChatParticipant"
          WHERE (("ChatParticipant".user_id = auth.uid()) AND ("ChatParticipant".is_active = true)))))));


