--
-- Name: BroadcastChannel BroadcastChannel_owner_all; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "BroadcastChannel_owner_all" ON public."BroadcastChannel" USING ((EXISTS ( SELECT 1
   FROM public."PublicPersona" pp
  WHERE ((pp.id = "BroadcastChannel".persona_id) AND (pp.user_id = (NULLIF(current_setting('request.jwt.claim.sub'::text, true), ''::text))::uuid))))) WITH CHECK ((EXISTS ( SELECT 1
   FROM public."PublicPersona" pp
  WHERE ((pp.id = "BroadcastChannel".persona_id) AND (pp.user_id = (NULLIF(current_setting('request.jwt.claim.sub'::text, true), ''::text))::uuid)))));


--
-- Name: BroadcastChannel BroadcastChannel_public_read; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY "BroadcastChannel_public_read" ON public."BroadcastChannel" FOR SELECT USING (((status = 'active'::text) AND (EXISTS ( SELECT 1
   FROM public."PublicPersona" pp
  WHERE ((pp.id = "BroadcastChannel".persona_id) AND (pp.status = 'active'::text))))));


