-- Name: Post post_persona_service_only; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY post_persona_service_only ON public."Post" AS RESTRICTIVE TO anon, authenticated USING (((COALESCE(identity_context_type, 'personal'::text) <> 'persona'::text) AND (COALESCE(post_as, 'personal'::public.post_as_type) <> 'persona'::public.post_as_type) AND (broadcast_channel_id IS NULL))) WITH CHECK (((COALESCE(identity_context_type, 'personal'::text) <> 'persona'::text) AND (COALESCE(post_as, 'personal'::public.post_as_type) <> 'persona'::public.post_as_type) AND (broadcast_channel_id IS NULL)));


--
-- Name: Post post_select_public; Type: POLICY; Schema: public; Owner: postgres
--

CREATE POLICY post_select_public ON public."Post" FOR SELECT USING ((((visibility)::text = 'public'::text) OR (user_id = auth.uid()) OR (((visibility)::text = 'neighborhood'::text) AND (EXISTS ( SELECT 1
   FROM public."User" u1,
    public."User" u2
  WHERE ((u1.id = auth.uid()) AND (u2.id = "Post".user_id) AND ((u1.city)::text = (u2.city)::text))))) OR (((visibility)::text = 'followers'::text) AND (EXISTS ( SELECT 1
   FROM public."UserFollow"
  WHERE (("UserFollow".follower_id = auth.uid()) AND ("UserFollow".following_id = "Post".user_id)))))));


